@app.put("/api/public-asset-storage/config")
def update_public_asset_storage_config(req: PublicAssetStorageConfigRequest):
    from models import get_kv, set_kv

    current = safe_json_loads(get_kv(PUBLIC_ASSET_STORAGE_KV_KEY, "{}"), {})
    if not isinstance(current, dict):
        current = {}
    next_config = {
        "provider": str(req.provider or "").strip().lower(),
        "local_base_url": str(req.local_base_url or "").strip(),
        "qiniu_access_key": str(req.qiniu_access_key).strip() if req.qiniu_access_key is not None and str(req.qiniu_access_key).strip() else str(current.get("qiniu_access_key") or "").strip(),
        "qiniu_secret_key": str(req.qiniu_secret_key).strip() if req.qiniu_secret_key is not None and str(req.qiniu_secret_key).strip() else str(current.get("qiniu_secret_key") or "").strip(),
        "qiniu_bucket": str(req.qiniu_bucket or "").strip(),
        "qiniu_region": str(req.qiniu_region or "z2").strip(),
        "qiniu_public_base_url": str(req.qiniu_public_base_url or "").strip().rstrip("/"),
        "qiniu_bucket_private": bool(req.qiniu_bucket_private),
        "qiniu_key_prefix": str(req.qiniu_key_prefix or "screenplay-agent").strip().strip("/"),
        "qiniu_upload_token_expires_seconds": max(int(req.qiniu_upload_token_expires_seconds or 3600), 60),
        "qiniu_public_url_ttl_seconds": max(int(req.qiniu_public_url_ttl_seconds or 86400), 300),
    }
    if next_config["provider"] not in {"", "qiniu"}:
        raise HTTPException(status_code=400, detail="当前对象存储配置第一版仅支持 qiniu。")
    set_kv(PUBLIC_ASSET_STORAGE_KV_KEY, json.dumps(next_config, ensure_ascii=False))
    return _storage_public_dict()


def _collect_storage_migration_assets(limit: int) -> list[dict[str, Any]]:
    from models import Session, StoryboardShot, VisualReferenceAsset

    rows: list[dict[str, Any]] = []

    def add_asset(source: str, owner: dict[str, Any], url: Any, locator: dict[str, Any]) -> None:
        text = str(url or "").strip()
        if not text or len(rows) >= limit:
            return
        rows.append({"source": source, "owner": owner, "url": text, "locator": locator})

    with Session() as s:
        reference_rows = s.query(VisualReferenceAsset).order_by(VisualReferenceAsset.id.asc()).limit(max(limit, 1000)).all()
        for row in reference_rows:
            if len(rows) >= limit:
                break
            owner = {
                "book_id": int(row.book_id),
                "episode": row.episode,
                "asset_type": row.asset_type,
                "asset_id": row.asset_id,
                "reference_id": row.id,
            }
            # The local copy remains a recovery source.  Migrating it updates
            # image_url, not local_path, so a rollback never loses the durable
            # local evidence.
            source_url = str(row.image_url or "").strip() or str(row.local_path or "").strip()
            source_kind = "visual_reference.image_url" if str(row.image_url or "").strip() else "visual_reference.local_path"
            add_asset(source_kind, owner, source_url, {
                "kind": "visual_reference",
                "reference_id": int(row.id),
                "field": "image_url",
                "source_field": "image_url" if str(row.image_url or "").strip() else "local_path",
            })

        shot_rows = s.query(StoryboardShot).order_by(StoryboardShot.book_id.asc(), StoryboardShot.episode.asc(), StoryboardShot.shot_id.asc()).limit(max(limit, 1000)).all()
        for shot in shot_rows:
            if len(rows) >= limit:
                break
            asset_links = _load_asset_links(shot.asset_links)
            owner = {
                "book_id": int(shot.book_id),
                "episode": int(shot.episode or 1),
                "shot_id": int(shot.shot_id),
                "scene_name": str(shot.scene_name or ""),
            }
            for group_key in ("images", "videos", "audios"):
                items = asset_links.get(group_key) if isinstance(asset_links, dict) else []
                if not isinstance(items, list):
                    continue
                for item in items:
                    if not isinstance(item, dict):
                        continue
                    asset_id = str(item.get("id") or "").strip()
                    if not asset_id:
                        continue
                    item_owner = {**owner, "asset_group": group_key, "asset_id": asset_id}
                    source_field = "uri" if str(item.get("uri") or "").strip() else "previewUrl"
                    source_url = item.get(source_field)
                    add_asset(f"storyboard.{group_key}.{source_field}", item_owner, source_url, {
                        "kind": "storyboard_asset",
                        "book_id": int(shot.book_id),
                        "episode": int(shot.episode or 1),
                        "shot_id": int(shot.shot_id),
                        "asset_group": group_key,
                        "asset_id": asset_id,
                        "field": source_field,
                    })
                    if len(rows) >= limit:
                        break
                if len(rows) >= limit:
                    break
    return rows


def _classify_storage_asset(url: str, target_base_url: str, *, check_external: bool = False) -> dict[str, Any]:
    text = str(url or "").strip()
    target = str(target_base_url or "").strip().rstrip("/")
    if target and text.startswith(target + "/"):
        return {"status": "already_target_storage", "requires_migration": False, "reason": "已在当前对象存储域名下"}
    if text.startswith("data:") or text.startswith("/") or text.startswith(("file:",)):
        return {"status": "needs_publish", "requires_migration": True, "reason": "本地或内联资产，需要发布到对象存储"}
    if text.startswith(("http://", "https://")):
        if not check_external:
            return {
                "status": "external_unchecked",
                "requires_migration": True,
                "reason": "外部 URL 未做在线可读性检查；如更换 OSS，需在执行迁移前深度核验。",
            }
        accessible, error = check_public_url_accessible(text, timeout_seconds=5.0)
        return {
            "status": "external_accessible" if accessible else "external_unreachable",
            "requires_migration": bool(accessible),
            "reason": "外部 URL 可读取，可迁移" if accessible else f"外部 URL 不可读取：{error}",
        }
    return {"status": "unknown_source", "requires_migration": False, "reason": "无法识别的资产地址"}


def _storage_migration_target_is_production_safe(storage_config) -> bool:
    """Do not permanently repoint production assets to Qiniu's temporary HTTP domain."""
    return public_asset_storage_is_production_safe(storage_config)


@app.get("/api/public-asset-storage/migration-plan")
def get_public_asset_storage_migration_plan(
    limit: int = Query(default=200, ge=1, le=2000),
    check_external: bool = Query(default=False),
):
    storage_config = load_public_asset_storage_config()
    assets = _collect_storage_migration_assets(limit)
    items = []
    summary = {
        "total_scanned": len(assets),
        "already_target_storage": 0,
        "needs_publish": 0,
        "external_unchecked": 0,
        "external_accessible": 0,
        "external_unreachable": 0,
        "unknown_source": 0,
        "requires_migration": 0,
    }


    for asset in assets:
        classification = _classify_storage_asset(
            asset["url"],
            storage_config.qiniu_public_base_url,
            check_external=check_external,
        )
        status = classification["status"]
        summary[status] = int(summary.get(status, 0)) + 1
        if classification["requires_migration"]:
            summary["requires_migration"] += 1
        items.append({**asset, **classification})
    plan_payload = {
        "storage": storage_config.public_dict(),
        "summary": summary,
        "items": items,
    }
    # A future writer must bind to this exact snapshot.  The plan intentionally
    # contains no secrets and does not mutate either old objects or DB links.
    confirmation_token = hashlib.sha256(
        json.dumps(plan_payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
    ).hexdigest()[:16]
    return {
        **plan_payload,
        "mode": "readonly-storage-migration-plan",
        "real_data_mutated": False,
        "confirmation_token": confirmation_token,
        "plan_fingerprint": confirmation_token,
        "requires_operator_confirmation": bool(summary["requires_migration"]),
        "migration_apply_supported": bool(storage_config.enabled and _storage_migration_target_is_production_safe(storage_config)),
        "migration_apply_note": (
            "已配置对象存储：可在复核当前计划后执行受保护迁移；迁移会保留旧对象，不会自动删除。"
            if storage_config.enabled and _storage_migration_target_is_production_safe(storage_config)
            else "当前只能生成只读计划：迁移写入要求已配置对象存储，并绑定非 clouddn.com 的自定义 HTTPS 访问域名。"
        ),
    }


def _storage_migration_public_record(row) -> dict[str, Any]:
    result = safe_json_loads(row.result, {})
    errors = safe_json_loads(row.error_report, [])
    return {
        "id": row.id,
        "task_id": row.task_id,
        "plan_fingerprint": row.plan_fingerprint,
        "status": row.status,
        "result": result if isinstance(result, dict) else {},
        "error_report": errors if isinstance(errors, list) else [],
        "old_objects_deleted": bool(row.old_objects_deleted),
        "confirmed_at": row.confirmed_at.isoformat() if row.confirmed_at else None,
        "started_at": row.started_at.isoformat() if row.started_at else None,
        "finished_at": row.finished_at.isoformat() if row.finished_at else None,
        "created_at": row.created_at.isoformat() if row.created_at else None,
        "updated_at": row.updated_at.isoformat() if row.updated_at else None,
    }


def _apply_storage_migration_reference(item: dict[str, Any], public_result) -> dict[str, Any]:
    """Change exactly one planned reference, retaining all original recovery data."""
    from models import Session, StoryboardShot, VisualReferenceAsset

    locator = item.get("locator") if isinstance(item.get("locator"), dict) else {}
    source_url = str(item.get("url") or "").strip()
    target_url = str(getattr(public_result, "public_url", "") or "").strip()
    if not locator or not source_url or not target_url:
        raise RuntimeError("storage_migration_invalid_item")

    with Session() as session:
        if locator.get("kind") == "visual_reference":
            row = session.query(VisualReferenceAsset).filter_by(id=int(locator.get("reference_id") or 0)).first()
            if not row:
                raise RuntimeError("storage_migration_reference_not_found")
            source_field = str(locator.get("source_field") or "image_url")
            current_source = str(getattr(row, source_field, "") or "").strip()
            if current_source != source_url:
                raise RuntimeError("storage_migration_source_changed")
            meta = safe_json_loads(row.meta_info, {})
            if not isinstance(meta, dict):
                meta = {}
            history = meta.get("storage_migrations") if isinstance(meta.get("storage_migrations"), list) else []
            history.append({
                "source_url": source_url,
                "target_url": target_url,
                "object_key": str(getattr(public_result, "object_key", "") or ""),
                "at": datetime.utcnow().isoformat(),
            })
            meta["storage_migrations"] = history[-20:]
            row.image_url = target_url
            row.meta_info = json.dumps(meta, ensure_ascii=False)
            row.updated_at = datetime.utcnow()
            session.commit()
        elif locator.get("kind") == "storyboard_asset":
            shot = session.query(StoryboardShot).filter_by(
                book_id=int(locator.get("book_id") or 0),
                episode=int(locator.get("episode") or 0),
                shot_id=int(locator.get("shot_id") or 0),
            ).first()
            if not shot:
                raise RuntimeError("storage_migration_storyboard_shot_not_found")
            links = _load_asset_links(shot.asset_links)
            group = str(locator.get("asset_group") or "")
            field = str(locator.get("field") or "")
            assets = links.get(group) if isinstance(links, dict) else None
            if not isinstance(assets, list) or field not in {"uri", "previewUrl"}:
                raise RuntimeError("storage_migration_storyboard_asset_invalid")
            matched = next((asset for asset in assets if isinstance(asset, dict) and str(asset.get("id") or "") == str(locator.get("asset_id") or "")), None)
            if not isinstance(matched, dict):
                raise RuntimeError("storage_migration_storyboard_asset_not_found")
            if str(matched.get(field) or "").strip() != source_url:
                raise RuntimeError("storage_migration_source_changed")
            metadata = matched.get("metadata") if isinstance(matched.get("metadata"), dict) else {}
            history = metadata.get("storageMigrations") if isinstance(metadata.get("storageMigrations"), list) else []
            history.append({"field": field, "sourceUrl": source_url, "targetUrl": target_url, "objectKey": str(getattr(public_result, "object_key", "") or ""), "at": datetime.utcnow().isoformat()})
            metadata["storageMigrations"] = history[-20:]
            matched["metadata"] = metadata
            matched[field] = target_url
            shot.asset_links = json.dumps(links, ensure_ascii=False)
            shot.updated_at = datetime.utcnow()
            session.commit()
        else:
            raise RuntimeError("storage_migration_locator_unsupported")
    return {
        "status": "migrated",
        "source": item.get("source"),
        "owner": item.get("owner"),
        "object_key": str(getattr(public_result, "object_key", "") or ""),
        "target_url": target_url.split("?", 1)[0],
        "bytes": int(getattr(public_result, "bytes_count", 0) or 0),
    }


def _run_public_asset_storage_migration(record_id: int) -> None:
    """Run an operator-confirmed plan once.  There is deliberately no auto retry."""
    from models import PublicAssetStorageMigrationRecord, Session

    with Session() as session:
        record = session.query(PublicAssetStorageMigrationRecord).filter_by(id=record_id).first()
        if not record:
            return
        plan = safe_json_loads(record.plan_snapshot, {})
        storage_snapshot = safe_json_loads(record.storage_snapshot, {})
        if not isinstance(plan, dict) or not isinstance(storage_snapshot, dict):
            record.status = "failed"; record.error_report = json.dumps([{"code": "invalid_migration_snapshot"}], ensure_ascii=False); record.finished_at = datetime.utcnow(); record.updated_at = datetime.utcnow(); session.commit(); return
        record.status = "running"; record.started_at = datetime.utcnow(); record.updated_at = datetime.utcnow(); session.commit()
        task_id = record.task_id

    current_storage = load_public_asset_storage_config()
    if not current_storage.enabled or current_storage.public_dict() != storage_snapshot:
        errors = [{"code": "storage_configuration_changed", "message": "对象存储配置已变化；请重新生成迁移计划并再次确认。"}]
        with Session() as session:
            record = session.query(PublicAssetStorageMigrationRecord).filter_by(id=record_id).first()
            if record:
                record.status = "failed"; record.error_report = json.dumps(errors, ensure_ascii=False); record.finished_at = datetime.utcnow(); record.updated_at = datetime.utcnow(); session.commit()
        _persist_task_state(task_id, "public-asset-storage-migration", {"task_id": task_id, "task_kind": "public-asset-storage-migration", "status": "failed", "progress": 100, "error": errors[0]["message"], "record_id": record_id, "old_objects_deleted": False, "finished_at": datetime.utcnow().isoformat()})
        return

    items = [item for item in plan.get("items", []) if isinstance(item, dict) and item.get("requires_migration")]
    migrated: list[dict[str, Any]] = []
    failures: list[dict[str, Any]] = []
    for index, item in enumerate(items, start=1):
        try:
            hint_seed = json.dumps(item.get("locator") or item.get("owner") or {}, ensure_ascii=False, sort_keys=True)
            hint = f"storage-migration-{hashlib.sha256(hint_seed.encode('utf-8')).hexdigest()[:16]}"
            published = ensure_provider_accessible_url(str(item.get("url") or ""), key_hint=hint, force_storage=True)
            if not published.ok:
                raise RuntimeError(str(published.error or "storage_publish_failed"))
            migrated.append(_apply_storage_migration_reference(item, published))
        except Exception as exc:
            failures.append({"source": item.get("source"), "owner": item.get("owner"), "error": str(exc), "retryable": True})
        progress = int(index * 100 / max(len(items), 1))
        result = {"total": len(items), "migrated": len(migrated), "failed": len(failures), "items": migrated, "old_objects_deleted": False}
        with Session() as session:
            record = session.query(PublicAssetStorageMigrationRecord).filter_by(id=record_id).first()
            if record:
                record.result = json.dumps(result, ensure_ascii=False); record.error_report = json.dumps(failures, ensure_ascii=False); record.updated_at = datetime.utcnow(); session.commit()
        _persist_task_state(task_id, "public-asset-storage-migration", {"task_id": task_id, "task_kind": "public-asset-storage-migration", "status": "running", "progress": progress, "record_id": record_id, "summary": {"total": len(items), "migrated": len(migrated), "failed": len(failures)}, "old_objects_deleted": False})

    status = "completed" if not failures else "partial" if migrated else "failed"
    result = {"total": len(items), "migrated": len(migrated), "failed": len(failures), "items": migrated, "old_objects_deleted": False}
    with Session() as session:
        record = session.query(PublicAssetStorageMigrationRecord).filter_by(id=record_id).first()
        if record:
            record.status = status; record.result = json.dumps(result, ensure_ascii=False); record.error_report = json.dumps(failures, ensure_ascii=False); record.finished_at = datetime.utcnow(); record.updated_at = datetime.utcnow(); session.commit()
    _persist_task_state(task_id, "public-asset-storage-migration", {"task_id": task_id, "task_kind": "public-asset-storage-migration", "status": status, "progress": 100, "record_id": record_id, "summary": {"total": len(items), "migrated": len(migrated), "failed": len(failures)}, "error": "迁移存在可人工重试的失败项" if failures else "", "old_objects_deleted": False, "finished_at": datetime.utcnow().isoformat()})


@app.get("/api/public-asset-storage/migration-records/{record_id}")
def get_public_asset_storage_migration_record(record_id: int):
    from models import PublicAssetStorageMigrationRecord, Session
    with Session() as session:
        record = session.query(PublicAssetStorageMigrationRecord).filter_by(id=record_id).first()
        if not record:
            raise HTTPException(status_code=404, detail="storage_migration_record_not_found")
        return _storage_migration_public_record(record)


@app.post("/api/public-asset-storage/migration-plan/execute")
def execute_public_asset_storage_migration_plan(req: PublicAssetStorageMigrationExecuteRequest, bg: BackgroundTasks):
    """Dry-run by default; write mode is explicitly confirmed and backgrounded."""
    plan = get_public_asset_storage_migration_plan(limit=req.limit, check_external=req.check_external)
    if str(req.confirmation_token or "").strip() != str(plan.get("confirmation_token") or ""):
        raise HTTPException(status_code=409, detail="storage_migration_plan_stale_or_unconfirmed")
    operator_requested_write = bool(req.confirmed and req.allow_write)
    requested_write = bool(req.execute_write)
    eligible_items = [item for item in plan["items"] if item.get("requires_migration")]
    if requested_write:
        if not (req.confirmed and req.allow_write):
            raise HTTPException(status_code=409, detail="storage_migration_write_requires_confirmed_and_allow_write")
        if str(req.execution_confirmation_token or "").strip() != "CONFIRM_PUBLIC_ASSET_STORAGE_MIGRATION":
            raise HTTPException(status_code=400, detail="storage_migration_write_requires_confirmation_token")
        storage = load_public_asset_storage_config()
        if not storage.enabled or not _storage_migration_target_is_production_safe(storage):
            raise HTTPException(status_code=409, detail="storage_migration_requires_custom_https_storage_domain")
        from models import PublicAssetStorageMigrationRecord, Session

        task_id = f"storage-migration-{uuid.uuid4().hex[:12]}"
        record = PublicAssetStorageMigrationRecord(
            plan_fingerprint=plan["plan_fingerprint"], status="queued", storage_snapshot=json.dumps(storage.public_dict(), ensure_ascii=False),
            plan_snapshot=json.dumps({"items": eligible_items, "summary": plan["summary"]}, ensure_ascii=False), task_id=task_id,
            confirmed_at=datetime.utcnow(), old_objects_deleted=False,
        )
        with Session() as session:
            session.add(record); session.commit(); session.refresh(record); record_id = record.id
        task_state = {"task_id": task_id, "task_kind": "public-asset-storage-migration", "status": "queued", "progress": 0, "record_id": record_id, "confirmation_token": plan["confirmation_token"], "summary": plan["summary"], "eligible_count": len(eligible_items), "old_objects_deleted": False, "created_at": datetime.utcnow().isoformat()}
        _persist_task_state(task_id, "public-asset-storage-migration", task_state)
        bg.add_task(_run_public_asset_storage_migration, record_id)
        return {"mode": "storage-migration-submitted", "real_data_mutated": False, "write_requested": True, "write_supported": True, "confirmation_token": plan["confirmation_token"], "summary": plan["summary"], "task_id": task_id, "record_id": record_id, "eligible_count": len(eligible_items), "old_objects_deleted": False, "automatic_retry": False}

    task_id = f"storage-migration-dryrun-{uuid.uuid4().hex[:12]}"
    task_state = {
        "task_id": task_id, "task_kind": "public-asset-storage-migration",
        "status": "dry_run", "progress": 100,
        "confirmation_token": plan["confirmation_token"],
        "summary": plan["summary"], "eligible_count": len(eligible_items),
        "write_requested": operator_requested_write, "old_objects_deleted": False,
        "created_at": datetime.utcnow().isoformat(), "finished_at": datetime.utcnow().isoformat(),
    }
    _persist_task_state(task_id, "public-asset-storage-migration", task_state)
    return {
        "mode": "storage-migration-dry-run", "real_data_mutated": False,
        "write_requested": operator_requested_write, "write_supported": False,
        "confirmation_token": plan["confirmation_token"], "summary": plan["summary"],
        "task_id": task_id, "eligible_items": eligible_items,
        "next_safe_step": "confirm_execute_write" if operator_requested_write else "review_and_confirm_current_plan",
        "old_objects_deleted": False,
    }


# --- Node execution ---

@app.post("/api/nodes/run")
def run_node(req: RunRequest, background: BackgroundTasks):
    run_id = str(uuid.uuid4())[:8]

    # Create runner
    runner = NodeRunner(node_type=req.node_type)
    runner.run_id = run_id
    runner.set_inputs(req.inputs)
    runner.set_config(req.config)

    _runs[run_id] = {"status": "running", "result": None, "runner": runner}

    handler = get_handler(req.node_type)
    if not handler:
        _runs[run_id] = {"status": "error", "result": {"error": f"Unknown node type: {req.node_type}"}}
        return {"run_id": run_id, "status": "error"}

    def execute():
        try:
            handler(runner)
            runner.save_snapshot()
            _runs[run_id] = {"status": "done", "result": runner._outputs, "runner": runner}
        except Exception as e:
            import traceback
            runner.add_log(f"ERROR: {e}")
            runner.set_meta("error", str(e))
            runner.set_meta("traceback", traceback.format_exc())
            runner.save_snapshot()
            _runs[run_id] = {"status": "error", "result": {"error": str(e)}, "runner": runner}

    background.add_task(execute)
    return {"run_id": run_id, "status": "running"}


@app.get("/api/nodes/run/{run_id}")
def get_run_status(run_id: str):
    run = _runs.get(run_id)
    if not run:
        raise HTTPException(status_code=404, detail="Run not found")

    resp = {
        "status": run["status"],
        "result": run["result"],
        "logs": run.get("runner", NodeRunner("")).logs if hasattr(run.get("runner"), "_logs") else [],
    }
    return resp


@app.get("/api/nodes/run/{run_id}/stream")
def stream_run_logs(run_id: str):
    """SSE stream for real-time log delivery."""
    from fastapi.responses import StreamingResponse
    import asyncio

    run = _runs.get(run_id)
    if not run:
        raise HTTPException(status_code=404, detail="Run not found")

    runner = run.get("runner")
    if not runner:
        raise HTTPException(status_code=400, detail="No runner")

    async def event_stream():
        seen = len(runner.logs)
        while True:
            current = len(runner.logs)
            if current > seen:
                for line in runner.logs[seen:]:
                    yield f"data: {line}\n\n"
                seen = current
            if run["status"] != "running":
                yield f"data: [STATUS] {run['status']}\n\n"
                break
            await asyncio.sleep(0.5)

    return StreamingResponse(event_stream(), media_type="text/event-stream")


@app.get("/api/runs")
def list_runs(node_type: str = ""):
    """List run snapshots, optionally filter by node_type."""
    if not RUNS_DIR.exists():
        return []
    runs = []
    for d in sorted(RUNS_DIR.iterdir(), reverse=True)[:50]:
        meta_file = d / "meta.json"
        if not meta_file.exists():
            continue
        meta = json.loads(meta_file.read_text(encoding="utf-8"))
        if node_type and meta.get("node_type", "") != node_type:
            continue
        # Read output summary
        output_file = d / "output.json"
        if output_file.exists():
            output = json.loads(output_file.read_text(encoding="utf-8"))
            meta["output_summary"] = {k: v for k, v in output.items()
                                        if k in ("output_path", "score")}
        runs.append(meta)
    return runs


@app.get("/api/runs/{run_id}/replay")
def replay_run(run_id: str, background: BackgroundTasks):
    """Replay a previous run with its exact inputs and config."""
    for d in RUNS_DIR.iterdir():
        if d.is_dir() and run_id in d.name:
            meta = json.loads((d / "meta.json").read_text(encoding="utf-8"))
            node_type = meta.get("node_type", "")
            inp_file = d / "input.json"
            cfg_file = d / "config.json"
            inputs = json.loads(inp_file.read_text(encoding="utf-8")) if inp_file.exists() else {}
            config = json.loads(cfg_file.read_text(encoding="utf-8")) if cfg_file.exists() else {}

            new_run_id = str(uuid.uuid4())[:8]
            runner = NodeRunner(node_type=node_type)
            runner.run_id = new_run_id
            runner.set_inputs(inputs)
            runner.set_config(config)
            _runs[new_run_id] = {"status": "running", "result": None, "runner": runner}

            handler = get_handler(node_type)
            if not handler:
                _runs[new_run_id] = {"status": "error", "result": {"error": f"Unknown node type: {node_type}"}}
                return {"run_id": new_run_id, "status": "error"}

            def execute():
                try:
                    handler(runner)
                    runner.save_snapshot()
                    _runs[new_run_id] = {"status": "done", "result": runner._outputs, "runner": runner}
                except Exception as e:
                    import traceback
                    runner.add_log(f"ERROR: {e}")
                    runner.set_meta("error", str(e))
                    runner.set_meta("traceback", traceback.format_exc())
                    runner.save_snapshot()
                    _runs[new_run_id] = {"status": "error", "result": {"error": str(e)}, "runner": runner}

            background.add_task(execute)
            return {"run_id": new_run_id, "status": "running", "replayed_from": run_id}

    raise HTTPException(status_code=404, detail="Run not found")


@app.get("/api/runs/{run_id}")
def get_run_snapshot(run_id: str):
    """Get full run snapshot data."""
    # Find by run_id prefix
    for d in RUNS_DIR.iterdir():
        if d.is_dir() and run_id in d.name:
            result = {}
            for f in d.iterdir():
                if f.suffix == ".json":
                    result[f.stem] = json.loads(f.read_text(encoding="utf-8"))
                elif f.suffix == ".txt":
                    result[f.stem] = f.read_text(encoding="utf-8")
            return result
    raise HTTPException(status_code=404, detail="Run not found")


@app.get("/api/search")
def search(query: str = ""):
    """Unified search: workflows, runs, prompts."""
    import fnmatch
    results = []
    q = query.lower().strip()

    if RUNS_DIR.exists():
        for d in RUNS_DIR.iterdir():
            if not d.is_dir():
                continue
            meta_file = d / "meta.json"
            if not meta_file.exists():
                continue
            meta = json.loads(meta_file.read_text(encoding="utf-8"))
            if q and q not in meta.get("node_type", "").lower():
                continue
            results.append({
                "type": "run",
                "id": meta.get("run_id", ""),
                "label": f"{meta.get('node_type', '?')} run",
                "sub": meta.get("started_at", "")[:19],
            })

    if WORKFLOWS_DIR.exists():
        for f in WORKFLOWS_DIR.glob("*.json"):
            data = json.loads(f.read_text(encoding="utf-8"))
            name = data.get("name", f.stem)
            if q and q not in name.lower():
                continue
            results.append({
                "type": "workflow",
                "id": f.stem,
                "label": name,
                "sub": f"{len(data.get('nodes', []))} nodes",
            })

    return results[:20]


@app.get("/api/runs/{run_id_a}/diff")
def diff_runs(run_id_a: str, run_id_b: str):
    """Compare two run outputs."""
    def load(run_id):
        for d in RUNS_DIR.iterdir():
            if d.is_dir() and run_id in d.name:
                inp = json.loads((d / "input.json").read_text(encoding="utf-8")) if (d / "input.json").exists() else {}
                out = json.loads((d / "output.json").read_text(encoding="utf-8")) if (d / "output.json").exists() else {}
                raw = (d / "raw_llm.json").read_text(encoding="utf-8") if (d / "raw_llm.json").exists() else ""
                return {"inputs": inp, "outputs": out, "raw_llm": raw[:2000]}
        return None

    a = load(run_id_a)
    b = load(run_id_b)
    if not a or not b:
        raise HTTPException(status_code=404, detail="Run not found")

    return {
        "left_run": run_id_a,
        "right_run": run_id_b,
        "left": a,
        "right": b,
        "input_match": a["inputs"] == b["inputs"],
        "output_match": a["outputs"] == b["outputs"],
    }


# === Pipeline API ===

class PipelineRequest(BaseModel):
    book_id: int = 0
    filepath: str = ""
    genre: str = "short_drama"
    episode_count: int = 20
    episode_duration: int = 3
    scope: str = "auto"
    scope_chapters: int = 0
    from_step: str | None = None
    stop_after: str | None = None
    preferred_title: str | None = Field(default=None, validation_alias=AliasChoices("preferred_title", "preferredTitle"))


# In-memory task tracking
_pipeline_tasks: dict[str, dict] = {}


@app.post("/api/pipeline/script")
async def run_script_pipeline(req: PipelineRequest, bg: BackgroundTasks):
    """Run the full script production pipeline as a background task."""
    import uuid
    from pathlib import Path

    task_id = uuid.uuid4().hex[:12]
    requested_episodes = list(range(1, max(int(req.episode_count or 0), 0) + 1))
    _pipeline_tasks[task_id] = {
        "status": "queued",
        "progress": 0,
        "current_step": "queued",
        "warnings": [],
        "book_id": req.book_id,
        "genre": req.genre,
        "requested_episodes": requested_episodes,
        "episodes": [_make_storyboard_episode_task(ep) for ep in requested_episodes],
        "started_at": datetime.utcnow().isoformat(),
        "finished_at": None,
        "error": None,
    }
    _summarize_storyboard_task(_pipeline_tasks[task_id])
    _persist_task_state(task_id, "pipeline", _pipeline_tasks[task_id])

    async def _run():
        try:
            _pipeline_tasks[task_id]["status"] = "running"
            _pipeline_tasks[task_id]["current_step"] = "starting"
            _persist_task_state(task_id, "pipeline", _pipeline_tasks[task_id])
            from models import Session, Book, Chapter, BookBible, EpisodeOutline, Script, StoryboardShot
            from core.ingest import ingest
            from agents.reader import ReaderAgent
            from agents.bible import BibleAgent
            from agents.portrait import PortraitAgent
            from agents.adapter import AdapterAgent
            from agents.outline import OutlineAgent
            from agents.scriptwriter import ScriptwriterAgent
            from agents.qa import QAAgent
            from agents.storyboard import StoryboardAgent

            book_id = req.book_id
            genre = req.genre
            ep_count = req.episode_count

            # Determine current pipeline stage from book status
            current_status = "imported"
            if not req.filepath:
                with Session() as s:
                    book_obj = s.get(Book, book_id)
                    if not book_obj:
                        _pipeline_tasks[task_id]["status"] = "error"
                        _pipeline_tasks[task_id]["current_step"] = "Book not found"
                        _pipeline_tasks[task_id]["finished_at"] = datetime.utcnow().isoformat()
                        _persist_task_state(task_id, "pipeline", _pipeline_tasks[task_id])
                        return
                    current_status = book_obj.status or "imported"

            status_ranks = {
                "imported": 0, "ingested": 1, "read": 1, "bibeled": 2,
                "portraited": 3, "adapted": 4, "outlined": 5, "scripted": 6,
                "storyboarded": 7,
            }
            rank = status_ranks.get(current_status, 0)

            # Check genre-specific progress
            with Session() as s:
                genre_outlines = s.query(EpisodeOutline).filter(
                    EpisodeOutline.book_id == book_id,
                    EpisodeOutline.genre == genre,
                ).count()
                genre_scripts = s.query(Script).filter(
                    Script.book_id == book_id,
                    Script.genre == genre,
                ).count()

            genre_adapted = genre_outlines > 0 or genre_scripts > 0
            genre_outlined = genre_outlines > 0

            # Count existing QA results to know if we need to re-run
            with Session() as s:
                from models import QAResult
                existing_qa = s.query(QAResult).filter(
                    QAResult.book_id == book_id
                ).count()

            steps = [
                ("ingest", rank < 0 or req.filepath != ""),
                ("read", rank < 1),
                ("bible", rank < 2),
                ("portrait", rank < 3),
                ("adapt", rank < 4 and not genre_adapted),
                ("outline", not genre_outlined),
                ("script", genre_outlined and genre_scripts < ep_count),
                ("qa", genre_outlined and genre_scripts > 0 and existing_qa < genre_scripts),
            ]

            script_steps_needed = max(0, ep_count - genre_scripts)
            base_steps = sum(1 for _, needed in steps if needed)
            total_steps = base_steps + script_steps_needed
            completed = 0
            non_blocking_warnings: list[str] = []

            def update_step(step_name: str):
                nonlocal completed
                completed += 1
                pct = min(99, int((completed / max(total_steps, 1)) * 100))
                _pipeline_tasks[task_id]["progress"] = pct
                _pipeline_tasks[task_id]["current_step"] = step_name
                _persist_task_state(task_id, "pipeline", _pipeline_tasks[task_id])

            # Handle filepath ingest at step level
            if req.filepath:
                update_step("瀵煎叆鏂囦欢")
                ingest_result = await asyncio.to_thread(ingest, req.filepath, req.preferred_title)
                book_id = ingest_result["book_id"]
                _pipeline_tasks[task_id]["new_book_id"] = book_id
                _pipeline_tasks[task_id]["book_id"] = book_id
                _persist_task_state(task_id, "pipeline", _pipeline_tasks[task_id])
                update_step("鏂囦欢瀵煎叆瀹屾垚")

            # Step: ingest (skip if already imported)
            if rank < 1:
                update_step("loading text")
                await asyncio.sleep(0.5)
                update_step("鍒嗗壊绔犺妭")
                # ingest can only be called if we have filepath
                # For existing books that are already imported, we skip
                if current_status == "imported":
                    update_step("ingest (no-op, no file)")
                update_step("ingest complete")

            # Step: read
            if rank < 1:
                update_step("閫愮珷鍒嗘瀽 (reader)")
                reader = ReaderAgent(book_id)
                # Apply scope via end_ch parameter (acts as limit)
                reader_limit = 0
                if req.scope == "first_n" and req.scope_chapters > 0:
                    reader_limit = req.scope_chapters
                await asyncio.to_thread(reader.run, None, reader_limit if reader_limit > 0 else None)
                update_step("reader complete")

            # Step: bible
            if rank < 2:
                update_step("生成世界观 Bible")
                bible_agent = BibleAgent(book_id)
                await asyncio.to_thread(bible_agent.run)
                update_step("bible complete")

            # Step: portrait
            if rank < 3:
                # Step: resolve aliases (before portrait)
                try:
                    from core.alias_resolver import resolve_aliases
                    with Session() as s:
                        update_step("归并角色别名")
                        resolve_aliases(book_id, s)
                        update_step("alias resolve complete")
                except Exception as resolve_exc:
                    logger.warning("Alias resolution failed (non-blocking): %s", resolve_exc)
                    non_blocking_warnings.append(f"别名归并已跳过：{resolve_exc}")

                update_step("生成人物画像")
                portrait_agent = PortraitAgent(book_id)
                try:
                    await asyncio.wait_for(asyncio.to_thread(portrait_agent.run), timeout=20)
                    update_step("portrait complete")
                except Exception as portrait_exc:
                    portrait_reason = str(portrait_exc).strip() or "portrait step timed out"
                    non_blocking_warnings.append(f"人物画像已跳过：{portrait_reason}")
                    _pipeline_tasks[task_id]["warnings"] = non_blocking_warnings
                    _pipeline_tasks[task_id]["current_step"] = "人物画像跳过，继续主链路"
                    _persist_task_state(task_id, "pipeline", _pipeline_tasks[task_id])

                # Step: portrait QA (auto-detect issues after portrait)
                try:
                    from core.portrait_qa import run_portrait_qa
                    with Session() as s:
                        qa_report = run_portrait_qa(book_id, s)
                        gender_authority_issues = [
                            issue for issue in qa_report.issues
                            if issue.issue_type in {"missing_gender", "makeup_gender_missing", "makeup_gender_conflict"}
                        ]
                        if gender_authority_issues:
                            non_blocking_warnings.append(
                                f"检测到 {len(gender_authority_issues)} 项人物性别权威事实问题；"
                                "请在「人物质检」完成修正后再生成定妆或提示词。"
                            )
                        if qa_report.gender_conflicts:
                            non_blocking_warnings.append(f"检测到 {len(qa_report.gender_conflicts)} 个人物性别冲突，请在「人物质检」面板中确认")
                        if qa_report.merge_candidates:
                            high_conf = [m for m in qa_report.merge_candidates if m.confidence == "high"]
                            if high_conf:
                                non_blocking_warnings.append(f"检测到 {len(high_conf)} 组高置信度疑似重复角色，请在「人物质检」面板中合并")
                        _pipeline_tasks[task_id]["warnings"] = non_blocking_warnings
                        _persist_task_state(task_id, "pipeline", _pipeline_tasks[task_id])
                except Exception as qa_exc:
                    logger.warning("Portrait QA failed (non-blocking): %s", qa_exc)

            if str(req.stop_after or "").strip().lower() == "content":
                with Session() as s:
                    book = s.get(Book, book_id)
                    if book:
                        current_book_status = str(book.status or "").strip().lower()
                        if current_book_status in {"", "draft", "imported", "ingested", "read"}:
                            book.status = "bibeled" if rank < 2 else (book.status or "bibeled")
                        s.commit()

                _pipeline_tasks[task_id]["status"] = "done"
                _pipeline_tasks[task_id]["progress"] = 100
                _pipeline_tasks[task_id]["current_step"] = "content preparation complete"
                _pipeline_tasks[task_id]["warnings"] = non_blocking_warnings
                _pipeline_tasks[task_id]["finished_at"] = datetime.utcnow().isoformat()
                _persist_task_state(task_id, "pipeline", _pipeline_tasks[task_id])
                return

            # Step: adapt (genre-specific, skip if already done for this genre)
            if rank < 4 and not genre_adapted:
                update_step("生成改编方案")
                adapt_agent = AdapterAgent(book_id, genre=genre)
                await asyncio.to_thread(adapt_agent.run)
                update_step("adapt complete")

            # Step: outline (genre-specific)
            if not genre_outlined:
                update_step("鐢熸垚鍒嗛泦澶х翰")
                outline_agent = OutlineAgent(book_id, genre=genre, episode_count=ep_count)
                await asyncio.to_thread(outline_agent.run)
                update_step("outline complete")

            # Step: script (genre-specific)
            # Determine how many episodes have outlines to write scripts for
            with Session() as s:
                actual_outlines = s.query(EpisodeOutline).filter(
                    EpisodeOutline.book_id == book_id,
                    EpisodeOutline.genre == genre,
                ).count()
            script_target = min(ep_count, actual_outlines) if actual_outlines > 0 else ep_count
            if genre_scripts < script_target:
                for ep in range(genre_scripts + 1, script_target + 1):
                    update_step(f"Generate episode {ep} script")
                    script_agent = ScriptwriterAgent(book_id, genre=genre)
                    await asyncio.to_thread(script_agent.run, ep)
                update_step("script writing complete")
            else:
                update_step("scripts already generated")

            # Step: QA (genre-specific, runs on all existing scripts)
            with Session() as s:
                from models import QAResult
                qa_count = s.query(QAResult).filter(
                    QAResult.book_id == book_id
                ).count()
            with Session() as s:
                actual_scripts = s.query(Script).filter(
                    Script.book_id == book_id,
                    Script.genre == genre,
                ).count()
            if qa_count < actual_scripts:
                qa_agent = QAAgent(book_id)
                for ep in range(1, actual_scripts + 1):
                    update_step(f"Run QA for episode {ep} script")
                    await asyncio.to_thread(qa_agent.run, ep)
                    # Materialise the freshly produced QA report into reviewable
                    # QAIssue rows so the controlled fix/auto-fix workflow has a
                    # target.  Without this, the QA report is produced but auto-fix
                    # and UI review find nothing to act on.
                    with Session() as qa_sync_session:
                        _sync_episode_qa_issues(qa_sync_session, book_id, ep)
                        qa_sync_session.commit()
                update_step("qa complete")

            with Session() as s:
                book = s.get(Book, book_id)
                if book:
                    book.status = "scripted"
                    s.commit()

            _pipeline_tasks[task_id]["status"] = "done"
            _pipeline_tasks[task_id]["progress"] = 100
            _pipeline_tasks[task_id]["warnings"] = non_blocking_warnings
            _pipeline_tasks[task_id]["finished_at"] = datetime.utcnow().isoformat()
            _persist_task_state(task_id, "pipeline", _pipeline_tasks[task_id])

        except Exception as exc:
            _pipeline_tasks[task_id]["status"] = "error"
            _pipeline_tasks[task_id]["current_step"] = str(exc)
            _pipeline_tasks[task_id]["error"] = str(exc)
            import traceback
            _pipeline_tasks[task_id]["traceback"] = traceback.format_exc()
            _pipeline_tasks[task_id]["finished_at"] = datetime.utcnow().isoformat()
            _persist_task_state(task_id, "pipeline", _pipeline_tasks[task_id])

    bg.add_task(_run)
    return {"task_id": task_id}


@app.get("/api/pipeline/task/{task_id}")
def get_pipeline_task(task_id: str):
    task = _pipeline_tasks.get(task_id)
    if not task:
        task = _load_persisted_task_state(task_id, "pipeline")
    if not task:
        raise HTTPException(status_code=404, detail="Pipeline task not found")
    _pipeline_tasks.setdefault(task_id, task)
    return task


class StoryboardRequest(BaseModel):
    book_id: int
    genre: str = "short_drama"
    episodes: Optional[list[int]] = None  # None = all
    # Production uses the director-LLM path by default.  The deterministic
    # fallback remains available only as an explicit safe-generation mode.
    generation_mode: str = Field(default="director_llm", validation_alias=AliasChoices("generation_mode", "generationMode"))
    force_llm: Optional[bool] = Field(default=None, validation_alias=AliasChoices("force_llm", "forceLlm"))
    resume_from_scene: dict[str, str] = Field(default_factory=dict, validation_alias=AliasChoices("resume_from_scene", "resumeFromScene"))
    require_shot_plan: bool = Field(
        default_factory=lambda: bool(config.REQUIRE_SHOT_PLAN_BY_DEFAULT),
        validation_alias=AliasChoices("require_shot_plan", "requireShotPlan"),
    )
    workflow_profile: str = Field(
        default="creative_draft",
        validation_alias=AliasChoices("workflow_profile", "workflowProfile"),
    )


def _make_storyboard_episode_task(episode: int) -> dict:
    return {
        "episode": int(episode),
        "status": "queued",
        "progress": 0,
        "current_step": "queued",
        "error": "",
        "failure_kind": "",
        "guidance": "",
        "shot_count": 0,
        "total_scenes": 0,
        "completed_scenes": 0,
        "current_scene": "",
        "last_completed_scene_name": "",
        "failed_scene_name": "",
        "resume_anchor": "",
        "retry_count": 0,
        "last_retry_reason": "",
        "warning_count": 0,
        "fallback_scene_count": 0,
        "started_at": None,
        "finished_at": None,
    }


def _summarize_storyboard_task(task: dict) -> None:
    episodes = task.get("episodes", [])
    if not isinstance(episodes, list) or not episodes:
        task["completed_episodes"] = 0
        task["failed_episodes"] = 0
        task["queued_episodes"] = 0
        return

    completed = sum(1 for item in episodes if item.get("status") == "done")
    failed = sum(1 for item in episodes if item.get("status") == "error")
    queued = sum(1 for item in episodes if item.get("status") in {"queued", "running"})
    task["completed_episodes"] = completed
    task["failed_episodes"] = failed
    task["queued_episodes"] = queued


def _classify_storyboard_failure(message: str) -> tuple[str, str]:
    text = str(message or "").strip().lower()
    if (
        "failed to parse llm json response" in text
        or "truncated" in text
        or "unexpected end" in text
        or "unterminated" in text
    ):
        return (
            "llm_truncated",
            "本集输出疑似被截断。建议只重试失败集；如已有场景进度，可从断点继续。",
        )
    if (
        "empty shots" in text
        or "returned empty" in text
        or "scene split" in text
        or "not a list" in text
        or "storyboard prompts are empty" in text
    ):
        return (
            "structure_invalid",
            "结构化分镜结果不完整。请先检查剧本分场和场景结构，再重试失败集。",
        )
    if "script not found" in text or "没有剧本" in text:
        return (
            "missing_script",
            "本集还没有可用剧本。请先完成剧本，再重新生成分镜。",
        )
    return (
        "unknown_error",
        "本集分镜生成失败。建议先重试失败集；若仍失败，再检查剧本和提示词上下文。",
    )


def _update_storyboard_episode_progress(task: dict, event: dict) -> None:
    episodes = task.get("episodes", [])
    if not isinstance(episodes, list):
        return

    episode = int(event.get("episode") or 0)
    if episode <= 0:
        return
    episode_task = next((item for item in episodes if int(item.get("episode", 0)) == episode), None)
    if not episode_task:
        return

    stage = str(event.get("stage") or "").strip()
    scene_name = str(event.get("scene_name") or "").strip()
    total_scenes = int(event.get("total_scenes") or episode_task.get("total_scenes") or 0)
    if total_scenes > 0:
        episode_task["total_scenes"] = total_scenes

    if stage == "scene_list_loaded":
        episode_task["progress"] = max(int(episode_task.get("progress") or 0), 5)
        episode_task["current_step"] = f"Detected {total_scenes} scenes"
        return

    if stage == "resume_initialized":
        completed_scenes = int(event.get("completed_scenes") or 0)
        resume_after_scene = str(event.get("resume_after_scene") or "").strip()
        if completed_scenes > 0:
            episode_task["completed_scenes"] = completed_scenes
            episode_task["last_completed_scene_name"] = resume_after_scene
            episode_task["resume_anchor"] = (
                f"已完成到第 {completed_scenes} 个场景"
                + (f"，可从 {resume_after_scene} 后继续" if resume_after_scene else "，可继续生成")
            )
        episode_task["current_step"] = episode_task.get("resume_anchor") or "Resume from breakpoint"
        episode_task["progress"] = max(int(episode_task.get("progress") or 0), 8)
        return

    if stage == "scene_started":
        episode_task["current_scene"] = scene_name
        episode_task["failed_scene_name"] = scene_name
        completed_scenes = int(episode_task.get("completed_scenes") or 0)
        if total_scenes > 0:
            ratio = completed_scenes / max(total_scenes, 1)
            episode_task["progress"] = max(int(episode_task.get("progress") or 0), min(95, 10 + int(ratio * 70)))
        episode_task["current_step"] = f"Generating scene: {scene_name or 'Unnamed scene'}"
        return

    if stage == "scene_retrying":
        episode_task["current_scene"] = scene_name or episode_task.get("current_scene") or ""
        episode_task["failed_scene_name"] = episode_task["current_scene"]
        current_scene_label = episode_task["current_scene"] or "scene"
        episode_task["current_step"] = f"Retrying scene automatically: {current_scene_label}"
        episode_task["retry_count"] = int(episode_task.get("retry_count") or 0) + 1
        episode_task["guidance"] = "The first generation attempt for this scene was incomplete. The system is retrying automatically."
        episode_task["last_retry_reason"] = str(event.get("reason") or "scene_retrying")
        episode_task["progress"] = max(int(episode_task.get("progress") or 0), 12)
        return

    if stage == "scene_fallback_used":
        episode_task["current_scene"] = scene_name or episode_task.get("current_scene") or ""
        episode_task["warning_count"] = int(episode_task.get("warning_count") or 0) + 1
        episode_task["fallback_scene_count"] = int(episode_task.get("fallback_scene_count") or 0) + 1
        episode_task["last_retry_reason"] = str(event.get("reason") or "scene_fallback_used")
        episode_task["guidance"] = "This scene fell back to the structured safe-generation path. Review it first after generation finishes."
        episode_task["current_step"] = f"Using fallback scene generation: {episode_task['current_scene'] or 'Unnamed scene'}"
        episode_task["progress"] = max(int(episode_task.get("progress") or 0), 18)
        return

    if stage == "scene_completed":
        completed_scenes = int(episode_task.get("completed_scenes") or 0) + 1
        episode_task["completed_scenes"] = completed_scenes
        episode_task["last_completed_scene_name"] = scene_name
        if total_scenes > 0:
            ratio = completed_scenes / max(total_scenes, 1)
            episode_task["progress"] = max(int(episode_task.get("progress") or 0), min(95, 15 + int(ratio * 75)))
            episode_task["resume_anchor"] = f"Completed {completed_scenes}/{total_scenes} scenes"
        else:
            episode_task["resume_anchor"] = f"Completed {completed_scenes} scenes"
        episode_task["current_step"] = f"Completed scene: {scene_name or 'Unnamed scene'}"


@app.post("/api/pipeline/storyboard")
async def run_storyboard(req: StoryboardRequest, bg: BackgroundTasks):
    """Run storyboard generation independently, optionally for selected episodes."""
    try:
        workflow_profile = resolve_workflow_profile(req.workflow_profile)
    except ValueError as exc:
        raise HTTPException(status_code=422, detail=str(exc)) from exc
    if workflow_profile == "production":
        # M0 deliberately fails closed until the later milestones provide the
        # required ScriptIR/ShotPlan/Compiler evidence.  Request flags cannot
        # weaken this boundary.
        gate = evaluate_production_boundary(
            workflow_profile,
            shot_plan_approved=False,
            script_ir_qualified=False,
            director_treatment_approved=False,
            scene_blocking_approved=False,
            compiler_phase_a_pass=False,
            executability_pass=False,
            required_assets_ready=False,
        )
        raise HTTPException(status_code=409, detail={"code": "PRODUCTION_BOUNDARY_BLOCKED", **gate})
    if req.require_shot_plan:
        requested = req.episodes or []
        with Session() as gate_session:
            missing = [
                int(ep) for ep in requested
                if not gate_session.query(ShotPlan).filter_by(book_id=req.book_id, episode=int(ep), status="approved").first()
            ]
        if missing:
            raise HTTPException(status_code=409, detail=f"ShotPlan gate blocked storyboard generation for episode(s): {', '.join(map(str, missing))}")
    import uuid
    generation_mode = str(req.generation_mode or "director_llm").strip().lower()
    if req.force_llm is not None:
        generation_mode = "director_llm" if req.force_llm else "deterministic_safe"
    if generation_mode not in {"director_llm", "deterministic_safe"}:
        raise HTTPException(status_code=422, detail="generation_mode must be director_llm or deterministic_safe")
    force_llm = generation_mode == "director_llm"
    task_id = uuid.uuid4().hex[:12]
    requested_episodes = sorted(set(int(ep) for ep in (req.episodes or []) if int(ep) > 0))
    _storyboard_tasks[task_id] = {
        "status": "running",
        "progress": 0,
        "current_step": "starting",
        "book_id": req.book_id,
        "genre": req.genre,
        "generation_mode": generation_mode,
        "workflow_profile": workflow_profile,
        "requested_episodes": requested_episodes,
        "episodes": [_make_storyboard_episode_task(ep) for ep in requested_episodes],
        "started_at": datetime.utcnow().isoformat(),
        "finished_at": None,
        "error": None,
    }
    _summarize_storyboard_task(_storyboard_tasks[task_id])
    _persist_task_state(task_id, "storyboard", _storyboard_tasks[task_id])

    def persist_storyboard_task() -> None:
        _summarize_storyboard_task(_storyboard_tasks[task_id])
        _persist_task_state(task_id, "storyboard", _storyboard_tasks[task_id])

    async def _run():
        try:
            from agents.storyboard import StoryboardAgent
            from models import Session, Script

            with Session() as s:
                q = s.query(Script).filter(
                    Script.book_id == req.book_id,
                    Script.genre == req.genre,
                )
                if req.episodes:
                    q = q.filter(Script.episode.in_(req.episodes))
                scripts = q.order_by(Script.episode).all()

            if not scripts:
                _storyboard_tasks[task_id]["status"] = "error"
                _storyboard_tasks[task_id]["current_step"] = "No scripts found. Generate scripts first."
                _storyboard_tasks[task_id]["finished_at"] = datetime.utcnow().isoformat()
                persist_storyboard_task()
                return

            sb_agent = StoryboardAgent(
                req.book_id,
                genre=req.genre,
                force_llm=force_llm,
                progress_callback=lambda event: (
                    _update_storyboard_episode_progress(_storyboard_tasks[task_id], event),
                    _persist_task_state(task_id, "storyboard", _storyboard_tasks[task_id]),
                ),
            )
            episodes = [int(sc.episode) for sc in scripts]
            _storyboard_tasks[task_id]["requested_episodes"] = episodes
            _storyboard_tasks[task_id]["episodes"] = [_make_storyboard_episode_task(ep) for ep in episodes]
            persist_storyboard_task()
            total = len(scripts)
            for i, sc in enumerate(scripts):
                episode_task = next(
                    (item for item in _storyboard_tasks[task_id]["episodes"] if int(item.get("episode", 0)) == int(sc.episode)),
                    None,
                )
                if episode_task:
                    episode_task["status"] = "running"
                    episode_task["progress"] = 10
                    episode_task["current_step"] = "starting"
                    episode_task["started_at"] = datetime.utcnow().isoformat()
                    resume_after_scene = str(req.resume_from_scene.get(str(sc.episode)) or "").strip()
                    if resume_after_scene:
                        episode_task["resume_anchor"] = f"Resume after scene {resume_after_scene}"
                else:
                    resume_after_scene = str(req.resume_from_scene.get(str(sc.episode)) or "").strip()
                _storyboard_tasks[task_id]["current_step"] = f"Generate episode {sc.episode} storyboard ({i + 1}/{total})"
                _persist_task_state(task_id, "storyboard", _storyboard_tasks[task_id])
                try:
                    shots = await asyncio.to_thread(sb_agent.run, sc.episode, resume_after_scene=resume_after_scene or None)
                    if req.require_shot_plan:
                        provenance = _attach_approved_shot_plan_refs(req.book_id, sc.episode)
                        if episode_task:
                            episode_task["shot_plan_provenance"] = provenance
                    if episode_task:
                        episode_task["status"] = "done"
                        episode_task["progress"] = 100
                        episode_task["current_step"] = "storyboard complete"
                        if int(episode_task.get("warning_count") or 0) > 0:
                            episode_task["current_step"] = "Storyboard done with fallback scenes"
                        episode_task["shot_count"] = len(shots or [])
                        episode_task["failure_kind"] = ""
                        episode_task["guidance"] = ""
                        if int(episode_task.get("warning_count") or 0) > 0:
                            episode_task["guidance"] = "Some scenes were auto-degraded to structured fallback shots. Please review those scenes first after generation."
                        episode_task["finished_at"] = datetime.utcnow().isoformat()
                except Exception as episode_exc:
                    failure_kind, guidance = _classify_storyboard_failure(str(episode_exc))
                    if episode_task:
                        episode_task["status"] = "error"
                        episode_task["progress"] = 100
                        episode_task["current_step"] = str(episode_exc)
                        episode_task["error"] = str(episode_exc)
                        episode_task["failure_kind"] = failure_kind
                        episode_task["guidance"] = guidance
                        if episode_task.get("last_completed_scene_name") and episode_task.get("resume_anchor"):
                            episode_task["guidance"] = (
                                f"{guidance} 当前已完成到 {episode_task['last_completed_scene_name']}，可优先从后续场景继续。"
                            )
                        episode_task["finished_at"] = datetime.utcnow().isoformat()
                finally:
                    pct = int(((i + 1) / total) * 100)
                    _storyboard_tasks[task_id]["progress"] = pct
                    persist_storyboard_task()

            completed = int(_storyboard_tasks[task_id].get("completed_episodes") or 0)
            failed = int(_storyboard_tasks[task_id].get("failed_episodes") or 0)
            if completed > 0 and failed > 0:
                _storyboard_tasks[task_id]["status"] = "partial"
                _storyboard_tasks[task_id]["current_step"] = (
                    f"Storyboard partially completed: {completed} succeeded, {failed} failed"
                )
            elif completed > 0:
                _storyboard_tasks[task_id]["status"] = "done"
                _storyboard_tasks[task_id]["current_step"] = "storyboard generation complete"
            else:
                _storyboard_tasks[task_id]["status"] = "error"
                _storyboard_tasks[task_id]["current_step"] = "storyboard generation failed"
            _storyboard_tasks[task_id]["progress"] = 100
            _storyboard_tasks[task_id]["finished_at"] = datetime.utcnow().isoformat()
            persist_storyboard_task()

        except Exception as exc:
            _storyboard_tasks[task_id]["status"] = "error"
            _storyboard_tasks[task_id]["current_step"] = str(exc)
            _storyboard_tasks[task_id]["error"] = str(exc)
            import traceback
            _storyboard_tasks[task_id]["traceback"] = traceback.format_exc()
            _storyboard_tasks[task_id]["finished_at"] = datetime.utcnow().isoformat()
        finally:
            persist_storyboard_task()

    bg.add_task(_run)
    return {"task_id": task_id}


_storyboard_tasks: dict = {}
_creative_tasks: dict[str, dict] = {}
_storyboard_prompt_compile_tasks: dict[str, dict] = {}


def _stamp_creative_task_state(task_state: dict[str, Any], *, created: bool = False) -> None:
    now = datetime.utcnow().isoformat()
    if created and not str(task_state.get("created_at") or "").strip():
        task_state["created_at"] = now
    task_state["updated_at"] = now
    task_id = str(task_state.get("task_id") or "").strip()
    if task_id:
        raw_kind = str(task_state.get("kind") or task_state.get("task_kind") or "").strip()
        if raw_kind in {"image", "video", "reference-image"}:
            task_kind = f"creative-{raw_kind}"
        elif raw_kind == "machine_prompt_api_submission":
            task_kind = "creative-machine_prompt_api_submission"
        elif raw_kind.startswith("creative"):
            task_kind = raw_kind
        else:
            target_kind = str(task_state.get("target_kind") or "creative").strip()
            task_kind = "creative-reference-image" if target_kind == "reference-image" else f"creative-{target_kind}"
        _persist_task_state(task_id, task_kind, task_state)


class CreativeGenerationRequest(BaseModel):
    model_config = ConfigDict(populate_by_name=True)

    book_id: int = Field(validation_alias=AliasChoices("book_id", "bookId"))
    episode: int
    shot_id: str = Field(validation_alias=AliasChoices("shot_id", "shotId"))
    source_node_id: str = Field(validation_alias=AliasChoices("source_node_id", "sourceNodeId"))
    source_asset_id: Optional[str] = Field(default=None, validation_alias=AliasChoices("source_asset_id", "sourceAssetId"))
    first_frame_asset_id: Optional[str] = Field(default=None, validation_alias=AliasChoices("first_frame_asset_id", "firstFrameAssetId"))
    first_frame_url: Optional[str] = Field(default=None, validation_alias=AliasChoices("first_frame_url", "firstFrameUrl"))
    asset_scope: Optional[str] = Field(default=None, validation_alias=AliasChoices("asset_scope", "assetScope"))
    asset_subject: Optional[str] = Field(default=None, validation_alias=AliasChoices("asset_subject", "assetSubject"))
    target_kind: Optional[str] = Field(default=None, validation_alias=AliasChoices("target_kind", "targetKind"))
    prompt: str = ""
    model: Optional[str] = None
    model_profile_id: Optional[str] = Field(default=None, validation_alias=AliasChoices("model_profile_id", "modelProfileId"))
    reference_asset_ids: list[str] = Field(default_factory=list, validation_alias=AliasChoices("reference_asset_ids", "referenceAssetIds"))
    reference_images: list[dict] = Field(default_factory=list, validation_alias=AliasChoices("reference_images", "referenceImages"))
    aspect_ratio: str = Field(default="16:9", validation_alias=AliasChoices("aspect_ratio", "aspectRatio"))
    negative_prompt: str = Field(default="", validation_alias=AliasChoices("negative_prompt", "negativePrompt"))
    # Scene reference generation can intentionally target a semantic layer.
    # The default keeps the historical combined contract; callers may request
    # a neutral canonical board, a state variant, or a Look variant without
    # mutating the stored asset first.
    scene_layer_mode: str = Field(default="combined", validation_alias=AliasChoices("scene_layer_mode", "sceneLayerMode"))
    duration_seconds: Optional[int] = Field(default=None, validation_alias=AliasChoices("duration_seconds", "durationSeconds"))
    count: int = 1
    simulate_error: bool = Field(default=False, validation_alias=AliasChoices("simulate_error", "simulateError"))
    # Real provider calls must be explicitly confirmed by the operator. Keep
    # the flags on the request itself so direct API clients cannot bypass the
    # UI confirmation boundary. Prototype-task-adapter remains safe for
    # deterministic tests and local previews, so it does not require these.
    confirmed: bool = False
    allow_external_call: bool = Field(default=False, validation_alias=AliasChoices("allow_external_call", "allowExternalCall"))


