@app.post("/api/books/{book_id}/storyboard/{episode}/{shot_id}/transition-frames/extract")
def extract_storyboard_transition_frame(
    book_id: int,
    episode: int,
    shot_id: int,
    req: StoryboardTransitionFrameExtractRequest,
):
    """Extract, persist, and register a candidate frame after explicit confirmation.

    This endpoint never locks the result and never generates a new video.  It
    only operates on an adopted, accepted source video from the adjacent shot.
    """
    from models import Session, StoryboardTransitionFrame

    if not (req.confirmed and req.allow_write):
        raise HTTPException(status_code=409, detail="Extracting a transition frame requires confirmed=true and allow_write=true.")
    if req.frame_kind not in {"last", "near_last"}:
        raise HTTPException(status_code=400, detail="frame_kind must be last or near_last.")
    if not public_asset_storage_enabled():
        raise HTTPException(status_code=409, detail="Transition-frame extraction requires configured public object storage so the next video model can access the frame.")

    with Session() as session:
        source, target = _find_storyboard_transition_pair(session, book_id, episode, shot_id, req.source_shot_id)
        if not _is_storyboard_shot_deliverable_for_export(source):
            raise HTTPException(status_code=409, detail="The source shot needs an adopted video with approved/accepted acceptance before a transition frame can be extracted.")
        source_video = _find_adopted_shot_asset(_load_asset_links(source.asset_links), "videos") or {}
        source_url = str(source_video.get("uri") or source_video.get("previewUrl") or "").strip()
        if not source_url:
            raise HTTPException(status_code=409, detail="The adopted source video has no readable URL.")

        try:
            source_bytes, content_type = _load_source_bytes(source_url, local_base_url=config.PUBLIC_ASSET_LOCAL_BASE_URL)
            if not source_bytes:
                raise RuntimeError("source_video_empty")
            source_suffix = ".mp4" if "mp4" in content_type.lower() else ".video"
            with tempfile.TemporaryDirectory(prefix="transition-frame-") as temp_dir:
                temp_path = Path(temp_dir)
                source_path = temp_path / f"source{source_suffix}"
                source_path.write_bytes(source_bytes)
                local_output_path = temp_path / "handoff-frame.png"
                extracted = extract_transition_frame(
                    source_path,
                    local_output_path,
                    frame_kind=req.frame_kind,
                    frame_time_ms=req.frame_time_ms,
                )
                checksum = str(extracted["checksum"])
                persistent_dir = config.UPLOAD_DIR / "transition-frames" / f"book-{book_id}" / f"episode-{episode}"
                persistent_dir.mkdir(parents=True, exist_ok=True)
                persistent_path = persistent_dir / f"source-{source.shot_id}-target-{target.shot_id}-{checksum[:16]}.png"
                if not persistent_path.exists():
                    persistent_path.write_bytes(local_output_path.read_bytes())
                extracted["local_path"] = str(persistent_path)
        except (OSError, RuntimeError, TransitionFrameExtractionError) as exc:
            raise HTTPException(status_code=400, detail=f"Transition frame extraction failed: {exc}") from exc

        checksum = str(extracted["checksum"])
        existing = session.query(StoryboardTransitionFrame).filter(
            StoryboardTransitionFrame.book_id == book_id,
            StoryboardTransitionFrame.episode == episode,
            StoryboardTransitionFrame.source_shot_id == source.shot_id,
            StoryboardTransitionFrame.target_shot_id == target.shot_id,
            StoryboardTransitionFrame.checksum == checksum,
        ).order_by(StoryboardTransitionFrame.id.desc()).first()
        if existing:
            return {"frame": _serialize_transition_frame(existing), "deduplicated": True, "mutated": False}

        public_result = ensure_provider_accessible_url(
            str(extracted["local_path"]),
            key_hint=f"book-{book_id}-episode-{episode}-source-{source.shot_id}-target-{target.shot_id}-transition-{req.frame_kind}",
            local_base_url=config.PUBLIC_ASSET_LOCAL_BASE_URL,
            force_storage=True,
            allow_unstable_storage=req.allow_unstable_public_assets,
        )
        if not public_result.ok or not public_result.public_url:
            raise HTTPException(status_code=400, detail=f"Transition frame was extracted locally but could not be published to object storage: {public_result.error or 'unknown_error'}")

        extraction_profile = dict(extracted["extraction_profile"])
        extraction_profile.update({
            "local_path": str(extracted["local_path"]),
            "source_url": source_url,
            "source_content_type": content_type,
            "storage_provider": public_result.storage_provider,
            "storage_uploaded": public_result.uploaded,
                "unstable_storage_override": bool(getattr(public_result, "unstable_storage_override", False)),
        })
        row = StoryboardTransitionFrame(
            book_id=book_id,
            episode=episode,
            source_shot_id=source.shot_id,
            target_shot_id=target.shot_id,
            source_video_asset_id=str(source_video.get("id") or ""),
            frame_time_ms=int(extracted["frame_time_ms"]),
            frame_kind=req.frame_kind,
            storage_key=public_result.object_key,
            public_url=public_result.public_url,
            checksum=checksum,
            width=int(extracted["width"]),
            height=int(extracted["height"]),
            status="candidate",
            extraction_profile=json.dumps(extraction_profile, ensure_ascii=False),
            notes=str(req.notes or "").strip(),
        )
        session.add(row)
        session.commit()
        session.refresh(row)
        return {"frame": _serialize_transition_frame(row), "deduplicated": False, "mutated": True}


@app.post("/api/books/{book_id}/storyboard/{episode}/{shot_id}/transition-frames")
def register_storyboard_transition_frame(
    book_id: int,
    episode: int,
    shot_id: int,
    req: StoryboardTransitionFrameRegisterRequest,
):
    from models import Session, StoryboardTransitionFrame

    if not (req.confirmed and req.allow_write):
        raise HTTPException(status_code=409, detail="Registering a transition frame requires confirmed=true and allow_write=true.")
    if req.frame_kind not in {"last", "near_last"}:
        raise HTTPException(status_code=400, detail="frame_kind must be last or near_last.")
    if not str(req.public_url or "").strip():
        raise HTTPException(status_code=400, detail="A provider-accessible public_url is required when registering a transition frame.")
    with Session() as session:
        source, target = _find_storyboard_transition_pair(session, book_id, episode, shot_id, req.source_shot_id)
        row = StoryboardTransitionFrame(
            book_id=book_id,
            episode=episode,
            source_shot_id=source.shot_id,
            target_shot_id=target.shot_id,
            source_video_asset_id=str(req.source_video_asset_id or "").strip(),
            frame_time_ms=req.frame_time_ms,
            frame_kind=req.frame_kind,
            storage_key=str(req.storage_key or "").strip(),
            public_url=str(req.public_url).strip(),
            checksum=str(req.checksum or "").strip(),
            width=req.width,
            height=req.height,
            extraction_profile=json.dumps(req.extraction_profile, ensure_ascii=False),
            notes=str(req.notes or "").strip(),
            status="candidate",
        )
        session.add(row)
        session.commit()
        session.refresh(row)
        return {"frame": _serialize_transition_frame(row)}


@app.post("/api/books/{book_id}/storyboard/{episode}/{shot_id}/transition-continuity-reviews/extract")
def extract_transition_continuity_review(book_id: int, episode: int, shot_id: int, req: StoryboardTransitionContinuityReviewRequest):
    """Extract target video's first frame for human comparison; no automatic scoring."""
    from models import Session, StoryboardTransitionFrame, StoryboardTransitionContinuityReview
    if not (req.confirmed and req.allow_write):
        raise HTTPException(status_code=409, detail="Creating a continuity review requires confirmed=true and allow_write=true.")
    if not public_asset_storage_enabled():
        raise HTTPException(status_code=409, detail="Continuity review extraction requires configured public object storage.")
    with Session() as session:
        source, target = _find_storyboard_transition_pair(session, book_id, episode, shot_id, req.source_shot_id)
        handoff = session.query(StoryboardTransitionFrame).filter_by(book_id=book_id, episode=episode, source_shot_id=source.shot_id, target_shot_id=target.shot_id, status="locked").order_by(StoryboardTransitionFrame.id.desc()).first()
        if not handoff:
            raise HTTPException(status_code=409, detail="A locked transition frame is required before extracting a continuity review frame.")
        video = _find_adopted_shot_asset(_load_asset_links(target.asset_links), "videos") or {}
        if req.target_video_asset_id and str(video.get("id") or "") != req.target_video_asset_id:
            raise HTTPException(status_code=409, detail="Selected target video is not the adopted video for this shot.")
        video_url = str(video.get("uri") or video.get("previewUrl") or "").strip()
        if not video_url:
            raise HTTPException(status_code=409, detail="Target shot needs an adopted video before continuity review.")
        try:
            raw, content_type = _load_source_bytes(video_url, local_base_url=config.PUBLIC_ASSET_LOCAL_BASE_URL)
            with tempfile.TemporaryDirectory(prefix="continuity-review-") as temp_dir:
                root = Path(temp_dir); source_path = root / ("target.mp4" if "mp4" in content_type.lower() else "target.video"); source_path.write_bytes(raw)
                output_path = root / "first.png"
                extracted = extract_transition_frame(source_path, output_path, frame_kind="last", frame_time_ms=0)
                checksum = str(extracted["checksum"])
                local_dir = config.UPLOAD_DIR / "transition-reviews" / f"book-{book_id}" / f"episode-{episode}"; local_dir.mkdir(parents=True, exist_ok=True)
                local_path = local_dir / f"source-{source.shot_id}-target-{target.shot_id}-{checksum[:16]}.png"
                if not local_path.exists(): local_path.write_bytes(output_path.read_bytes())
        except (OSError, RuntimeError, TransitionFrameExtractionError) as exc:
            raise HTTPException(status_code=400, detail=f"Target first-frame extraction failed: {exc}") from exc
        public = ensure_provider_accessible_url(
            str(local_path),
            key_hint=f"book-{book_id}-episode-{episode}-source-{source.shot_id}-target-{target.shot_id}-review-first",
            force_storage=True,
            allow_unstable_storage=req.allow_unstable_public_assets,
        )
        if not public.ok or not public.public_url:
            raise HTTPException(status_code=400, detail=f"Target first frame could not be published: {public.error or 'unknown_error'}")
        session.query(StoryboardTransitionContinuityReview).filter_by(book_id=book_id, episode=episode, source_shot_id=source.shot_id, target_shot_id=target.shot_id, status="candidate").update({"status": "superseded", "updated_at": datetime.utcnow()})
        row = StoryboardTransitionContinuityReview(book_id=book_id, episode=episode, source_shot_id=source.shot_id, target_shot_id=target.shot_id, transition_frame_id=handoff.id, target_video_asset_id=str(video.get("id") or ""), target_first_frame_url=public.public_url, target_first_frame_storage_key=public.object_key, target_first_frame_checksum=checksum)
        session.add(row); session.commit(); session.refresh(row)
        return {"review": {"id": row.id, "status": row.status, "transition_frame_id": row.transition_frame_id, "target_first_frame_url": row.target_first_frame_url, "target_first_frame_checksum": row.target_first_frame_checksum}, "mutated": True}


@app.patch("/api/books/{book_id}/storyboard/{episode}/{shot_id}/transition-continuity-reviews/{review_id}")
def review_storyboard_transition_continuity(book_id: int, episode: int, shot_id: int, review_id: int, req: StoryboardTransitionContinuityReviewPatchRequest):
    from models import Session, StoryboardTransitionContinuityReview
    if req.review_result not in {"pass", "warning", "fail"}:
        raise HTTPException(status_code=400, detail="review_result must be pass, warning, or fail.")
    if not (req.confirmed and req.allow_write):
        raise HTTPException(status_code=409, detail="Reviewing continuity requires confirmed=true and allow_write=true.")
    allowed = {"identity_drift", "costume_drift", "scene_drift", "prop_drift", "composition_jump"}
    if set(req.drift_categories) - allowed:
        raise HTTPException(status_code=400, detail="Unsupported continuity drift category.")
    with Session() as session:
        source, target = _find_storyboard_transition_pair(session, book_id, episode, shot_id)
        row = session.query(StoryboardTransitionContinuityReview).filter_by(id=review_id, book_id=book_id, episode=episode, source_shot_id=source.shot_id, target_shot_id=target.shot_id).first()
        if not row: raise HTTPException(status_code=404, detail="Continuity review not found.")
        row.status="reviewed"; row.review_result=req.review_result; row.drift_categories=json.dumps(sorted(set(req.drift_categories)), ensure_ascii=False); row.review_notes=req.review_notes; row.reviewed_at=datetime.utcnow(); row.updated_at=datetime.utcnow(); session.commit()
        return {"review": {"id": row.id, "status": row.status, "review_result": row.review_result, "drift_categories": safe_json_loads(row.drift_categories, []), "review_notes": row.review_notes}}


@app.patch("/api/books/{book_id}/storyboard/{episode}/{shot_id}/transition-frames/{frame_id}")
def update_storyboard_transition_frame_status(
    book_id: int,
    episode: int,
    shot_id: int,
    frame_id: int,
    req: StoryboardTransitionFrameStatusRequest,
):
    from models import Session, StoryboardTransitionFrame

    status = str(req.status or "").strip().lower()
    if status not in {"candidate", "selected", "locked", "superseded"}:
        raise HTTPException(status_code=400, detail="Unsupported transition frame status.")
    if not (req.confirmed and req.allow_write):
        raise HTTPException(status_code=409, detail="Changing transition frame status requires confirmed=true and allow_write=true.")
    with Session() as session:
        source, target = _find_storyboard_transition_pair(session, book_id, episode, shot_id)
        row = session.query(StoryboardTransitionFrame).filter(
            StoryboardTransitionFrame.id == frame_id,
            StoryboardTransitionFrame.book_id == book_id,
            StoryboardTransitionFrame.episode == episode,
            StoryboardTransitionFrame.source_shot_id == source.shot_id,
            StoryboardTransitionFrame.target_shot_id == target.shot_id,
        ).first()
        if not row:
            raise HTTPException(status_code=404, detail="Transition frame not found for this adjacent shot pair.")
        if status == "locked":
            session.query(StoryboardTransitionFrame).filter(
                StoryboardTransitionFrame.book_id == book_id,
                StoryboardTransitionFrame.episode == episode,
                StoryboardTransitionFrame.source_shot_id == source.shot_id,
                StoryboardTransitionFrame.target_shot_id == target.shot_id,
                StoryboardTransitionFrame.id != row.id,
                StoryboardTransitionFrame.status == "locked",
            ).update({"status": "superseded", "updated_at": datetime.utcnow()})
        row.status = status
        row.updated_at = datetime.utcnow()
        session.commit()
        return {"frame": _serialize_transition_frame(row)}


def _resolve_optional_storyboard_first_frame(shot, *, first_frame_asset_id: str | None = None) -> tuple[str, str]:
    asset_links = _load_asset_links(shot.asset_links)
    requested_id = str(first_frame_asset_id or "").strip()
    first_frame_asset = None
    if requested_id:
        first_frame_asset = _find_shot_asset_by_id(asset_links, "images", requested_id)
        if not first_frame_asset:
            raise HTTPException(status_code=400, detail="Selected first-frame image was not found on this shot.")
    else:
        first_frame_asset = _find_adopted_shot_asset(asset_links, "images")
    if not first_frame_asset:
        return "", ""
    first_frame_url = str(first_frame_asset.get("uri") or first_frame_asset.get("previewUrl") or "").strip()
    if not first_frame_url:
        raise HTTPException(status_code=400, detail="The selected first-frame image is missing a usable preview URL.")
    return str(first_frame_asset.get("id") or "").strip(), first_frame_url


def _resolve_provider_ready_storyboard_first_frame(
    shot,
    *,
    first_frame_asset_id: str | None = None,
    allow_unstable_storage: bool = False,
) -> tuple[str, str, dict[str, Any]]:
    # A locked continuity handoff frame is a first-frame source even when it
    # is not present in the target shot's ordinary image asset links.  Resolve
    # it through the transition-frame registry and scope the lookup to the
    # exact target shot; this keeps continuity references reproducible without
    # introducing shot-specific behavior.
    requested_id = str(first_frame_asset_id or "").strip()
    resolved_asset_id = ""
    source_url = ""
    if requested_id.startswith("transition-frame-"):
        raw_frame_id = requested_id.removeprefix("transition-frame-").strip()
        try:
            frame_id = int(raw_frame_id)
        except (TypeError, ValueError):
            frame_id = 0
        if frame_id:
            from models import Session, StoryboardTransitionFrame

            with Session() as session:
                row = session.query(StoryboardTransitionFrame).filter(
                    StoryboardTransitionFrame.id == frame_id,
                    StoryboardTransitionFrame.book_id == int(getattr(shot, "book_id", 0) or 0),
                    StoryboardTransitionFrame.episode == int(getattr(shot, "episode", 0) or 0),
                    StoryboardTransitionFrame.target_shot_id == _coerce_storyboard_shot_id(getattr(shot, "shot_id", 0)),
                    StoryboardTransitionFrame.status == "locked",
                ).first()
                if row:
                    resolved_asset_id = requested_id
                    source_url = str(row.public_url or "").strip()

    if not source_url:
        resolved_asset_id, source_url = _resolve_optional_storyboard_first_frame(shot, first_frame_asset_id=first_frame_asset_id)
    if not source_url:
        return "", "", {}
    key_hint = f"book-{getattr(shot, 'book_id', '')}-episode-{getattr(shot, 'episode', '')}-shot-{getattr(shot, 'shot_id', '')}-first-frame"
    public_result = ensure_provider_accessible_url(
        source_url,
        key_hint=key_hint,
        local_base_url=config.PUBLIC_ASSET_LOCAL_BASE_URL,
        allow_unstable_storage=allow_unstable_storage,
    )
    public_dict = public_result.to_dict()
    if not public_result.ok:
        storage_hint = "；已配置七牛资产中转，但源图无法读取或中转 URL 不可访问" if public_asset_storage_enabled() else "；请先配置七牛资产中转或改用公网可访问首帧"
        raise HTTPException(
            status_code=400,
            detail=f"首帧图无法被外部视频模型访问：{public_result.error or 'unknown_error'}{storage_hint}。",
        )
    return resolved_asset_id, public_result.public_url or source_url, public_dict


def _model_max_reference_images(profile: dict[str, Any], default: int = 9) -> int:
    params = profile.get("default_params") if isinstance(profile, dict) else {}
    params = params if isinstance(params, dict) else {}
    try:
        return max(int(params.get("max_reference_images") or default), 1)
    except (TypeError, ValueError):
        return default


def _resolve_provider_ready_storyboard_reference_images(
    shot,
    *,
    requested_reference_asset_ids: list[str] | None = None,
    max_reference_images: int | None = None,
    include_composition_reference: bool = False,
    allow_unstable_storage: bool = False,
) -> tuple[list[str], list[dict[str, Any]], list[dict[str, Any]]]:
    if include_composition_reference:
        reference_asset_ids, reference_images = _resolve_storyboard_video_reference_payloads(
            shot,
            requested_reference_asset_ids,
            max_reference_images=max_reference_images,
        )
    else:
        reference_asset_ids, reference_images = _resolve_storyboard_reference_payloads(shot, requested_reference_asset_ids)
    provider_ready_images: list[dict[str, Any]] = []
    public_assets: list[dict[str, Any]] = []

    provider_limit = max(int(max_reference_images or 9), 1)
    for index, item in enumerate(reference_images[:provider_limit], start=1):
        if not isinstance(item, dict):
            continue
        source_url = str(item.get("image_url") or item.get("imageUrl") or item.get("url") or "").strip()
        reference_asset_id = str(item.get("reference_asset_id") or item.get("referenceAssetId") or item.get("asset_id") or "").strip()
        if not source_url or not reference_asset_id:
            continue
        key_hint = (
            f"book-{getattr(shot, 'book_id', '')}-episode-{getattr(shot, 'episode', '')}-"
            f"shot-{getattr(shot, 'shot_id', '')}-reference-{index}-{reference_asset_id}"
        )
        public_result = ensure_provider_accessible_url(
            source_url,
            key_hint=key_hint,
            local_base_url=config.PUBLIC_ASSET_LOCAL_BASE_URL,
            force_storage=True,
            allow_unstable_storage=allow_unstable_storage,
        )
        public_dict = public_result.to_dict()
        public_dict["reference_asset_id"] = reference_asset_id
        public_assets.append(public_dict)
        if not public_result.ok:
            storage_hint = "；已配置七牛资产中转，但参考图源文件无法读取或中转 URL 不可访问" if public_asset_storage_enabled() else "；请先配置七牛资产中转或改用公网可访问参考图"
            raise HTTPException(
                status_code=400,
                detail=f"H3 多参考图 {reference_asset_id or f'#{index}'} 无法被外部视频模型访问：{public_result.error or 'unknown_error'}{storage_hint}。",
            )
        provider_item = dict(item)
        provider_item["image_url"] = public_result.public_url or source_url
        provider_ready_images.append(provider_item)

    provider_ready_asset_ids = [
        str(item.get("reference_asset_id") or item.get("referenceAssetId") or item.get("asset_id") or "").strip()
        for item in provider_ready_images
        if str(item.get("reference_asset_id") or item.get("referenceAssetId") or item.get("asset_id") or "").strip()
    ]
    return list(dict.fromkeys(provider_ready_asset_ids or reference_asset_ids[: len(provider_ready_images)])), provider_ready_images, public_assets


def _is_unstable_public_reference_url(url: str) -> bool:
    """Return whether a reference URL is a temporary/insecure Qiniu URL.

    A URL can be reachable from this machine and still be unsuitable for a
    production provider request.  Keep this check local to the read-only
    media preflight so the actual submission path remains the final authority.
    """
    from urllib.parse import urlparse

    try:
        parsed = urlparse(str(url or "").strip())
    except ValueError:
        return False
    host = str(parsed.hostname or "").strip().lower()
    return bool(
        parsed.scheme != "https"
        or host == "clouddn.com"
        or host.endswith(".clouddn.com")
    )


def _build_storyboard_media_preflight(
    shot,
    *,
    target_model: str = "minimax-h3",
    model_profile_id: str | None = None,
    use_reference_images: bool = True,
    use_first_frame: bool = False,
    requested_reference_asset_ids: list[str] | None = None,
    allow_unstable_public_assets: bool = False,
) -> dict[str, Any]:
    """Build a provider-input report without publishing or mutating anything.

    This deliberately does not call ``ensure_provider_accessible_url``: that
    helper may upload local files to object storage.  The preflight only checks
    already-public URLs and reports which references would need publishing.
    The confirmed submission endpoint performs the authoritative publish and
    capability checks again.
    """
    from urllib.parse import urlparse

    target_model = str(target_model or "minimax-h3").strip() or "minimax-h3"
    blockers: list[str] = []
    warnings: list[str] = []
    reference_results: list[dict[str, Any]] = []
    first_frame_result: dict[str, Any] = {}

    try:
        profile = resolve_generation_profile("video", model_profile_id or None)
    except (ModelProfileError, ValueError) as exc:
        profile = {}
        blockers.append("video_model_profile_unavailable")
        warnings.append(str(exc))

    provider = str(profile.get("provider") or "").strip()
    model_name = str(profile.get("model_name") or "").strip()
    params = profile.get("default_params") if isinstance(profile, dict) else {}
    params = params if isinstance(params, dict) else {}
    try:
        max_reference_images = max(int(params.get("max_reference_images") or 9), 1)
    except (TypeError, ValueError):
        max_reference_images = 9

    # Read-only preflight cannot upload or download source bytes.  It can,
    # however, determine whether the authoritative submit path has a valid
    # publication bridge.  Treat local/inaccessible references as ready when
    # that bridge is configured and explicitly safe (or the request-scoped
    # gray-test override is enabled); the submit endpoint will still perform
    # the real publish and remains the final authority on failures.
    storage_config = load_public_asset_storage_config()
    storage_base = urlparse(str(getattr(storage_config, "qiniu_public_base_url", "") or "").strip())
    temporary_storage_override = bool(
        getattr(storage_config, "provider", "") == "qiniu"
        and storage_base.scheme == "http"
        and str(storage_base.hostname or "").strip().lower().endswith(".clouddn.com")
    )
    storage_can_publish = bool(
        storage_config.enabled
        and (
            public_asset_storage_is_production_safe(storage_config)
            or (allow_unstable_public_assets and temporary_storage_override)
        )
    )

    if provider and provider not in {MINIMAX_H3_ASYNC_PROVIDER, MINIMAX_H3_75API_PROVIDER}:
        blockers.append("video_provider_not_supported_for_h3_submission")
    if provider == MINIMAX_H3_75API_PROVIDER and not use_reference_images and not use_first_frame:
        blockers.append("75api_h3_requires_image_input")

    if use_reference_images:
        try:
            _, reference_images = _resolve_storyboard_video_reference_payloads(
                shot,
                requested_reference_asset_ids,
                max_reference_images=max_reference_images,
            )
        except HTTPException as exc:
            reference_images = []
            blockers.append("reference_image_limit_exceeded")
            warnings.append(str(exc.detail))

        if not reference_images:
            # Distinguish an unbound shot from a shot whose structured assets
            # exist but have not yet been carried into a compiled Prompt
            # Version.  Both are blocked, but the latter has a deterministic
            # next action: compile/review the prompt before media submission.
            shot_meta = safe_json_loads(getattr(shot, "meta_info", "") or "{}")
            shot_meta = shot_meta if isinstance(shot_meta, dict) else {}
            structured = shot_meta.get("structured_shot", {}) if isinstance(shot_meta.get("structured_shot", {}), dict) else {}
            declared_assets = bool(
                str(structured.get("scene_asset_id") or "").strip()
                or structured.get("character_asset_ids")
                or structured.get("prop_asset_ids")
            )
            blockers.append("prompt_compiler_references_missing" if declared_assets else "no_reference_images_selected")
        for index, item in enumerate(reference_images, start=1):
            if not isinstance(item, dict):
                continue
            source_url = str(item.get("image_url") or item.get("imageUrl") or item.get("url") or "").strip()
            reference_asset_id = str(item.get("reference_asset_id") or item.get("asset_id") or "").strip()
            result: dict[str, Any] = {
                "index": index,
                "reference_asset_id": reference_asset_id,
                "asset_type": str(item.get("asset_type") or item.get("role") or "").strip(),
                "label": str(item.get("asset_name") or item.get("label") or "").strip(),
                "source_url": source_url,
                "accessible": False,
                "requires_publish": False,
                "publishable_via_storage": storage_can_publish,
                "unstable_url": False,
                "error": "",
            }
            if not source_url:
                result["error"] = "missing_url"
                blockers.append("reference_missing_url")
            elif source_url.startswith("data:") or source_url.startswith("/"):
                result["requires_publish"] = True
                result["error"] = "not_public_url"
                if not storage_can_publish:
                    blockers.append("compiled_reference_images_not_provider_accessible")
                else:
                    warnings.append("reference_will_be_published_before_submit")
            elif source_url.startswith(("http://", "https://")):
                accessible, error = check_public_url_accessible(source_url, timeout_seconds=3.0, attempts=1)
                result["accessible"] = bool(accessible)
                result["error"] = str(error or "")
                result["unstable_url"] = _is_unstable_public_reference_url(source_url)
                if not accessible:
                    result["requires_publish"] = True
                    if not storage_can_publish:
                        blockers.append("compiled_reference_images_not_provider_accessible")
                    else:
                        warnings.append("reference_will_be_published_before_submit")
                elif result["unstable_url"] and not allow_unstable_public_assets:
                    blockers.append("reference_public_url_unstable")
            else:
                result["requires_publish"] = True
                result["error"] = "unsupported_url_scheme"
                if not storage_can_publish:
                    blockers.append("compiled_reference_images_not_provider_accessible")
                else:
                    warnings.append("reference_will_be_published_before_submit")
            reference_results.append(result)

    if use_first_frame:
        source_url = ""
        asset_links = _load_asset_links(getattr(shot, "asset_links", None))
        adopted = _find_adopted_shot_asset(asset_links, "images")
        if isinstance(adopted, dict):
            source_url = str(adopted.get("uri") or adopted.get("previewUrl") or "").strip()
            first_frame_result["asset_id"] = str(adopted.get("id") or "").strip()
        first_frame_result.update({"source_url": source_url, "accessible": False, "requires_publish": False, "error": ""})
        if not source_url:
            blockers.append("no_adopted_first_frame")
            first_frame_result["error"] = "missing_url"
        elif source_url.startswith("data:") or source_url.startswith("/"):
            first_frame_result["requires_publish"] = True
            first_frame_result["error"] = "not_public_url"
            first_frame_result["publishable_via_storage"] = storage_can_publish
            if not storage_can_publish:
                blockers.append("selected_first_frame_url_not_provider_accessible")
            else:
                warnings.append("first_frame_will_be_published_before_submit")
        else:
            accessible, error = check_public_url_accessible(source_url, timeout_seconds=3.0, attempts=1)
            first_frame_result["accessible"] = bool(accessible)
            first_frame_result["error"] = str(error or "")
            first_frame_result["unstable_url"] = _is_unstable_public_reference_url(source_url)
            if not accessible:
                first_frame_result["requires_publish"] = True
                first_frame_result["publishable_via_storage"] = storage_can_publish
                if not storage_can_publish:
                    blockers.append("selected_first_frame_url_not_provider_accessible")
                else:
                    warnings.append("first_frame_will_be_published_before_submit")
            elif first_frame_result["unstable_url"] and not allow_unstable_public_assets:
                blockers.append("first_frame_public_url_unstable")

    # Preserve order while deduplicating repeated findings from multiple refs.
    blockers = list(dict.fromkeys(blockers))
    warnings = list(dict.fromkeys(warnings))
    return {
        "mode": "readonly-storyboard-media-preflight",
        "book_id": int(getattr(shot, "book_id", 0) or 0),
        "episode": int(getattr(shot, "episode", 0) or 0),
        "shot_id": int(getattr(shot, "shot_id", 0) or 0),
        "scene_name": str(getattr(shot, "scene_name", "") or "").strip(),
        "target_model": target_model,
        "model": {
            "profile_id": str(profile.get("id") or ""),
            "name": str(profile.get("name") or ""),
            "provider": provider,
            "model_name": model_name,
            "max_reference_images": max_reference_images,
            "enabled": bool(profile.get("enabled", False)),
        },
        "input_mode": {
            "use_reference_images": bool(use_reference_images),
            "use_first_frame": bool(use_first_frame),
            "reference_count": len(reference_results),
        },
        "references": reference_results,
        "first_frame": first_frame_result,
        "ready_for_real_submit": not blockers,
        "blockers": blockers,
        "warnings": warnings,
        "mutated": False,
        "provider_call": False,
    }


def _resolve_storyboard_video_continuity_policy(session, shot, profile: dict[str, Any], reference_images: list[dict[str, Any]]) -> dict[str, Any]:
    """Load only confirmed/locked continuity records for the target shot.

    Absence of a contract keeps legacy generation available.  A confirmed strict
    contract, however, is a production gate: it must never be silently degraded
    to a different visual-input mode.
    """
    from models import StoryboardTransitionContract, StoryboardTransitionFrame

    try:
        source, target = _find_storyboard_transition_pair(
            session,
            int(shot.book_id),
            int(shot.episode),
            int(shot.shot_id),
        )
    except HTTPException as exc:
        if exc.status_code == 409:
            return {
                "strategy": "legacy_input_selection",
                "continuity_level": "independent",
                "first_frame_url": "",
                "reference_images": reference_images,
                "blocking_issues": [],
                "warnings": ["first-shot-has-no-predecessor"],
                "capability_snapshot": {},
                "contract": None,
                "transition_frame": None,
            }
        raise
    contract = session.query(StoryboardTransitionContract).filter(
        StoryboardTransitionContract.book_id == shot.book_id,
        StoryboardTransitionContract.episode == shot.episode,
        StoryboardTransitionContract.source_shot_id == source.shot_id,
        StoryboardTransitionContract.target_shot_id == target.shot_id,
        StoryboardTransitionContract.status == "confirmed",
    ).order_by(StoryboardTransitionContract.version.desc()).first()
    if not contract:
        return {
            "strategy": "legacy_input_selection",
            "continuity_level": "independent",
            "first_frame_url": "",
            "reference_images": reference_images,
            "blocking_issues": [],
            "warnings": [],
            "capability_snapshot": {},
            "contract": None,
            "transition_frame": None,
        }
    frame = session.query(StoryboardTransitionFrame).filter(
        StoryboardTransitionFrame.book_id == shot.book_id,
        StoryboardTransitionFrame.episode == shot.episode,
        StoryboardTransitionFrame.source_shot_id == source.shot_id,
        StoryboardTransitionFrame.target_shot_id == target.shot_id,
        StoryboardTransitionFrame.status == "locked",
    ).order_by(StoryboardTransitionFrame.updated_at.desc(), StoryboardTransitionFrame.id.desc()).first()
    source_video = _find_adopted_shot_asset(_load_asset_links(source.asset_links), "videos") or {}
    source_video_asset_id = str(source_video.get("id") or "").strip()
    if frame and _transition_evidence_status(
        frame,
        None,
        source_video_asset_id=source_video_asset_id,
        target_video_asset_id="",
    ) == "stale":
        # A locked frame is evidence for one exact source video.  Do not feed a
        # frame from an older cut to a provider after a new video is adopted.
        frame = None
    policy = resolve_video_continuity_strategy(
        contract=_serialize_transition_contract(contract),
        transition_frame=_serialize_transition_frame(frame) if frame else None,
        model_profile=profile,
        reference_images=reference_images,
    )
    policy["contract"] = _serialize_transition_contract(contract)
    policy["transition_frame"] = _serialize_transition_frame(frame) if frame else None
    if not frame and source_video_asset_id:
        policy["warnings"] = list(policy.get("warnings") or []) + ["locked-transition-frame-is-stale-for-current-source-video"]
    return policy


def _append_video_continuity_contract_to_prompt(prompt: str, continuity_policy: dict[str, Any] | None) -> str:
    """Compile a confirmed continuity contract into a provider-facing prompt.

    A continuity contract is not merely audit metadata: for soft continuity it
    is the only vendor-neutral way to preserve identity and spatial facts while
    still permitting an editorial cut.  Strict contracts additionally have a
    locked handoff frame, but retain this text constraint for the portions of
    the state that remain visible after camera reframing.
    """
    policy = continuity_policy if isinstance(continuity_policy, dict) else {}
    contract = policy.get("contract") if isinstance(policy.get("contract"), dict) else {}
    if str(contract.get("status") or "").strip().lower() != "confirmed":
        return prompt
    level = str(contract.get("continuity_level") or policy.get("continuity_level") or "").strip().lower()
    if level not in {"soft", "strict", "narrative"}:
        return prompt

    def text(value: Any) -> str:
        return " ".join(str(value or "").split()).strip()

    inherited = contract.get("inherit_rules") if isinstance(contract.get("inherit_rules"), dict) else {}
    inherit_values = [text(value) for value in inherited.values() if text(value)]
    allowed = [text(value) for value in (contract.get("allowed_changes") or []) if text(value)]
    forbidden = [text(value) for value in (contract.get("forbidden_changes") or []) if text(value)]
    clauses = [
        f"Confirmed {level} continuity contract.",
        f"Required entry state: {text(contract.get('entry_state'))}." if text(contract.get("entry_state")) else "",
        f"Required exit state: {text(contract.get('exit_state'))}." if text(contract.get("exit_state")) else "",
        f"Preserve: {'; '.join(inherit_values)}." if inherit_values else "",
        f"Only these declared changes are allowed: {'; '.join(allowed)}." if allowed else "",
        f"Never: {'; '.join(forbidden)}." if forbidden else "",
    ]
    block = " ".join(clause for clause in clauses if clause)
    return f"{prompt.rstrip()} {block}".strip()


@app.post("/api/prototyping/tasks/{task_id}/submit-machine-prompt-provider")
async def submit_machine_prompt_api_task_to_provider(
    task_id: str,
    req: StoryboardMachinePromptProviderSubmitRequest,
    bg: BackgroundTasks,
):
    if str(req.confirmation_token or "").strip() != "CONFIRM_MINIMAX_H3_SUBMIT":
        raise HTTPException(status_code=400, detail="真实提交 MiniMax H3 前必须提供确认口令 CONFIRM_MINIMAX_H3_SUBMIT。")
    if req.use_reference_images and req.use_first_frame:
        raise HTTPException(
            status_code=409,
            detail="MiniMax H3 多参考图与首/尾帧模式互斥。请在确认提交前明确选择多参考图或首帧模式。",
        )

    task_state = _creative_tasks.get(task_id)
    if not task_state:
        task_state = _load_persisted_task_state(task_id)
        if _is_creative_task_state(task_state):
            _creative_tasks[task_id] = task_state
        else:
            task_state = None
    if not task_state:
        raise HTTPException(status_code=404, detail="Task not found")

    if str(task_state.get("generation_chain") or "").strip() != "machine_prompt_api_submission":
        raise HTTPException(status_code=400, detail="Only machine prompt API submission tasks can be submitted through this endpoint.")
    if bool(task_state.get("actual_provider_submission")) and str(task_state.get("external_task_id") or "").strip():
        raise HTTPException(status_code=409, detail="This machine prompt task has already been submitted to a provider.")
    if str(task_state.get("status") or "").strip() in {"running", "done"} and bool(task_state.get("actual_provider_submission")):
        raise HTTPException(status_code=409, detail="This machine prompt task is already running or completed as a provider submission.")

    request_payload = task_state.get("request_payload")
    if not isinstance(request_payload, dict):
        raise HTTPException(status_code=400, detail="Task request payload is unavailable.")
    export_payload = request_payload.get("export_payload") if isinstance(request_payload.get("export_payload"), dict) else {}
    frozen_model_profile_id = str(
        task_state.get("model_profile_id")
        or request_payload.get("model_profile_id")
        or req.model_profile_id
        or ""
    ).strip()
    if (
        frozen_model_profile_id
        and req.model_profile_id
        and str(req.model_profile_id).strip() != frozen_model_profile_id
    ):
        raise HTTPException(status_code=409, detail="提交任务绑定的模型配置已冻结，不能在确认时切换模型。")
    # Resolve the frozen profile before collecting references so provider
    # limits (for example 75api's eight-image cap) are applied from the same
    # model that will actually receive the request.
    try:
        frozen_profile = resolve_generation_profile("video", frozen_model_profile_id or None)
    except (ModelProfileError, ValueError):
        frozen_profile = None
    target_model = str(task_state.get("target_model") or request_payload.get("target_model") or "minimax-h3").strip() or "minimax-h3"
    prompt_text = ""

    book_id = int(task_state.get("book_id") or request_payload.get("book_id") or 0)
    episode = int(task_state.get("episode") or request_payload.get("episode") or 0)
    shot_id = str(task_state.get("shot_id") or request_payload.get("shot_id") or "").strip()
    if not book_id or not episode or not shot_id:
        raise HTTPException(status_code=400, detail="Machine prompt task is missing storyboard identity fields.")

    from models import Session, StoryboardShot

    with Session() as s:
        shot = s.query(StoryboardShot).filter(
            StoryboardShot.book_id == book_id,
            StoryboardShot.episode == episode,
            StoryboardShot.shot_id == _coerce_storyboard_shot_id(shot_id),
        ).first()
        if not shot:
            raise HTTPException(status_code=404, detail="Storyboard shot not found")

        first_frame_asset_id = ""
        first_frame_url = ""
        first_frame_public_asset = {}
        reference_asset_ids: list[str] = []
        reference_images: list[dict[str, Any]] = []
        reference_public_assets: list[dict[str, Any]] = []
        if req.use_reference_images:
            reference_asset_ids, reference_images, reference_public_assets = _resolve_provider_ready_storyboard_reference_images(
                shot,
                requested_reference_asset_ids=req.reference_asset_ids,
                max_reference_images=_model_max_reference_images(frozen_profile or {}, default=9),
                include_composition_reference=True,
                allow_unstable_storage=req.allow_unstable_public_assets,
            )
            if not reference_images:
                raise HTTPException(status_code=409, detail="已选择 MiniMax H3 多参考图模式，但当前镜头没有可用的参考图。")
        if req.use_first_frame:
            first_frame_asset_id, first_frame_url, first_frame_public_asset = _resolve_provider_ready_storyboard_first_frame(
                shot,
                first_frame_asset_id=req.first_frame_asset_id,
                allow_unstable_storage=req.allow_unstable_public_assets,
            )

        # Recompile the provider-facing export after the input mode is known.
        # A saved preview may contain ordinary scene/character references,
        # while strict first-frame mode deliberately sends only the locked
        # handoff frame.  The text must describe the exact payload that will
        # be submitted, otherwise the model receives contradictory guidance.
        if req.use_first_frame and not req.use_reference_images:
            export_payload = _preview_storyboard_machine_prompt_export(
                book_id,
                shot,
                target_model,
                reference_images_override=[],
            )
        prompt_text = _extract_h3_prompt_from_machine_prompt_payload(export_payload, target_model)
        if not prompt_text:
            raise HTTPException(status_code=400, detail="Machine prompt export payload does not contain a usable MiniMax H3 prompt.")

    creative_req = CreativeGenerationRequest(
        book_id=book_id,
        episode=episode,
        shot_id=shot_id,
        source_node_id=f"machine-prompt-api-{episode}-{shot_id}",
        source_asset_id=first_frame_asset_id or None,
        first_frame_asset_id=first_frame_asset_id or None,
        first_frame_url=first_frame_url or None,
        asset_scope="shot",
        asset_subject=shot_id,
        target_kind="video",
        prompt=prompt_text,
        negative_prompt="",
        model_profile_id=req.model_profile_id,
        reference_asset_ids=reference_asset_ids,
        reference_images=reference_images,
        aspect_ratio=req.aspect_ratio,
        duration_seconds=req.duration_seconds,
    )

    # When a task was registered from the formal workspace, use the frozen
    # profile id unless an older API caller intentionally omitted one.
    if frozen_model_profile_id:
        creative_req = creative_req.model_copy(update={"model_profile_id": frozen_model_profile_id})

    try:
        profile = _resolve_creative_profile(creative_req, "video")
    except (ModelProfileError, ValueError) as exc:
        raise HTTPException(status_code=400, detail=str(exc)) from exc
    provider_name = str(profile.get("provider") or "").strip()
    if provider_name not in {MINIMAX_H3_ASYNC_PROVIDER, MINIMAX_H3_75API_PROVIDER}:
        raise HTTPException(status_code=400, detail="真实机器提示词 API 提交目前只允许使用已接入的 MiniMax H3 视频模型。请先在模型管理中选择 Metaso H3 或 75api H3 配置。")
    if provider_name == MINIMAX_H3_75API_PROVIDER and not (reference_images or first_frame_url):
        raise HTTPException(status_code=409, detail="75api MiniMax H3 不支持文生视频，必须先提供首帧图或多参考图。")

    version = _next_asset_version(book_id, episode, shot_id, "video")
    task_state.update({
        "status": "queued",
        "progress": max(int(task_state.get("progress") or 0), 10),
        "target_kind": "video",
        "version": version,
        "model_profile_id": profile.get("id"),
        "provider": profile.get("provider"),
        "uses_mock": False,
        "external_task_id": None,
        "external_status": "queued_for_minimax_h3_submission",
        "poll_attempts": 0,
        "provider_response": None,
        "provider_request_payload": None,
        "actual_provider_submission": True,
        "submission_mode": "confirmed_provider_submission",
        "first_frame_asset_id": first_frame_asset_id,
        "first_frame_url": first_frame_url,
        "first_frame_public_asset": first_frame_public_asset,
        "reference_asset_ids": reference_asset_ids,
        "reference_images": reference_images,
        "reference_public_assets": reference_public_assets,
        "provider_task_mode": "reference_to_video" if reference_images else "image_to_video" if first_frame_url else "text_to_video",
        "provider_submission_confirmed_at": datetime.utcnow().isoformat(),
        "provider_submission_notes": str(req.notes or "").strip(),
        "prompt_encoding_audit": _build_provider_prompt_encoding_audit(prompt_text),
        "request_payload": {
            **creative_req.model_dump(mode="json", by_alias=False),
            "generation_chain": "machine_prompt_api_submission",
            "api_submission": True,
            "actual_provider_submission": True,
            "target_model": target_model,
            "source_export_record_id": request_payload.get("source_export_record_id"),
            "has_manual_export_draft": bool(request_payload.get("has_manual_export_draft")),
            "export_payload": export_payload,
            "provider_submission_confirmed_at": datetime.utcnow().isoformat(),
            "first_frame_public_asset": first_frame_public_asset,
            "reference_public_assets": reference_public_assets,
        },
    })
    _stamp_creative_task_state(task_state)
    bg.add_task(_run_creative_task, task_id, "video", creative_req)
    return {
        "task_id": task_id,
        "status": task_state["status"],
        "progress": task_state["progress"],
        "book_id": book_id,
        "episode": episode,
        "shot_id": shot_id,
        "target_model": target_model,
        "generation_chain": "machine_prompt_api_submission",
        "provider": profile.get("provider"),
        "model_profile_id": profile.get("id"),
        "external_status": task_state["external_status"],
        "api_submission": True,
        "actual_provider_submission": True,
        "first_frame_asset_id": first_frame_asset_id,
        "first_frame_url": first_frame_url,
        "first_frame_public_asset": first_frame_public_asset,
        "reference_asset_ids": reference_asset_ids,
        "reference_images": reference_images,
        "reference_public_assets": reference_public_assets,
        "provider_task_mode": task_state["provider_task_mode"],
    }


@app.post("/api/books/{book_id}/storyboard/{episode}/{shot_id}/compile-prompts")
def compile_storyboard_prompts(book_id: int, episode: int, shot_id: str, req: StoryboardPromptCompileRequest):
    from models import Session, StoryboardShot

    if not (req.confirmed and req.allow_external_call):
        raise HTTPException(status_code=409, detail="直接重编译会调用 LLM；请改用候选草案，或显式传 confirmed=true 和 allowExternalCall=true。")

    with Session() as s:
        shot = s.query(StoryboardShot).filter(
            StoryboardShot.book_id == book_id,
            StoryboardShot.episode == episode,
            StoryboardShot.shot_id == _coerce_storyboard_shot_id(shot_id),
        ).first()
        if not shot:
            raise HTTPException(status_code=404, detail="Storyboard shot not found")
        shot_meta = safe_json_loads(shot.meta_info) if shot.meta_info else {}
        if not isinstance(shot_meta, dict):
            shot_meta = {}
        prompt_compiler_meta = shot_meta.get("prompt_compiler", {}) if isinstance(shot_meta.get("prompt_compiler", {}), dict) else {}
        if prompt_compiler_meta.get("locked") and not req.force:
            raise HTTPException(status_code=409, detail="Storyboard prompt version is locked. Unlock or force compile to continue.")

        result = _persist_storyboard_prompt_compile(s, book_id, episode, shot, req.compile_reason)
        s.commit()
        s.refresh(result["row"])

        return {
            "book_id": book_id,
            "episode": episode,
            "shot_id": shot.shot_id,
            "version": result["row"].version,
            "prompt_static": result["row"].prompt_static,
            "prompt_motion": result["row"].prompt_motion,
            "negative_prompt": result["row"].negative_prompt,
            "acceptance_feedback": result["compiled"].get("acceptance_feedback", {}),
            "locked_reference_summary": result["compiled"].get("locked_reference_summary", {}),
            "prompt_compile_context": result["compiled"].get("prompt_compile_context", {}),
            "used_assets": result["compiled"].get("used_assets", []),
            "reference_images": result["compiled"].get("reference_images", []),
            "reference_asset_ids": result["compiled"].get("reference_asset_ids", []),
            "compiler_warnings": result["compiled"].get("compiler_warnings", []),
            "compiler_diagnostics": result["compiled"].get("compiler_diagnostics", {}),
            "repair_attempted": bool(result["compiled"].get("repair_attempted")),
            "llm_request_audit": result["compiled"].get("llm_request_audit", {}),
        }


async def _run_storyboard_prompt_compile_task(
    task_id: str,
    book_id: int,
    episode: int,
    shot_id: str,
    compile_reason: str,
):
    from models import Session, StoryboardShot

    task_state = _storyboard_prompt_compile_tasks[task_id]
    try:
        task_state["status"] = "running"
        task_state["progress"] = 15
        _stamp_creative_task_state(task_state)

        with Session() as s:
            shot = s.query(StoryboardShot).filter(
                StoryboardShot.book_id == book_id,
                StoryboardShot.episode == episode,
                StoryboardShot.shot_id == _coerce_storyboard_shot_id(shot_id),
            ).first()
            if not shot:
                raise RuntimeError("Storyboard shot not found")

            task_state["progress"] = 45
            _stamp_creative_task_state(task_state)
            result = _persist_storyboard_prompt_compile(s, book_id, episode, shot, compile_reason)
            s.commit()
            s.refresh(result["row"])

            compiled = result["compiled"]
            task_state["status"] = "done"
            task_state["progress"] = 100
            task_state["prompt_version"] = result["row"].version
            task_state["version"] = result["row"].version
            task_state["compile_reason"] = compile_reason
            task_state["repair_attempted"] = bool(compiled.get("repair_attempted"))
            task_state["compiler_diagnostics"] = compiled.get("compiler_diagnostics", {})
            task_state["compiler_warnings"] = compiled.get("compiler_warnings", [])
            task_state["reference_asset_ids"] = compiled.get("reference_asset_ids", [])
            task_state["result"] = {
                "book_id": book_id,
                "episode": episode,
                "shot_id": shot.shot_id,
                "version": result["row"].version,
                "prompt_static": result["row"].prompt_static,
                "prompt_motion": result["row"].prompt_motion,
                "negative_prompt": result["row"].negative_prompt,
                "repair_attempted": bool(compiled.get("repair_attempted")),
            }
            _stamp_creative_task_state(task_state)
    except Exception as exc:
        task_state = _storyboard_prompt_compile_tasks[task_id]
        task_state["status"] = "error"
        task_state["progress"] = max(int(task_state.get("progress") or 0), 15)
        task_state["error"] = str(exc)
        _stamp_creative_task_state(task_state)


@app.post("/api/books/{book_id}/storyboard/{episode}/{shot_id}/compile-prompts/async")
async def compile_storyboard_prompts_async(
    book_id: int,
    episode: int,
    shot_id: str,
    req: StoryboardPromptCompileRequest,
    bg: BackgroundTasks,
):
    from models import Session, StoryboardShot

    if not (req.confirmed and req.allow_external_call):
        raise HTTPException(status_code=409, detail="直接重编译会调用 LLM；请改用候选草案，或显式传 confirmed=true 和 allowExternalCall=true。")

    with Session() as s:
        shot = s.query(StoryboardShot).filter(
            StoryboardShot.book_id == book_id,
            StoryboardShot.episode == episode,
            StoryboardShot.shot_id == _coerce_storyboard_shot_id(shot_id),
        ).first()
        if not shot:
            raise HTTPException(status_code=404, detail="Storyboard shot not found")

        shot_meta = safe_json_loads(shot.meta_info) if shot.meta_info else {}
        if not isinstance(shot_meta, dict):
            shot_meta = {}
        prompt_compiler_meta = shot_meta.get("prompt_compiler", {}) if isinstance(shot_meta.get("prompt_compiler", {}), dict) else {}
        if prompt_compiler_meta.get("locked") and not req.force:
            raise HTTPException(status_code=409, detail="Storyboard prompt version is locked. Unlock or force compile to continue.")

    task_id = uuid.uuid4().hex[:12]
    _storyboard_prompt_compile_tasks[task_id] = {
        "task_id": task_id,
        "kind": "storyboard-prompt-compile",
        "status": "queued",
        "progress": 0,
        "book_id": book_id,
        "episode": episode,
        "shot_id": _coerce_storyboard_shot_id(shot_id),
        "compile_reason": req.compile_reason,
        "prompt_version": None,
        "error": None,
    }
    _stamp_creative_task_state(_storyboard_prompt_compile_tasks[task_id], created=True)

    def _run_compile_in_thread():
        asyncio.run(_run_storyboard_prompt_compile_task(task_id, book_id, episode, shot_id, req.compile_reason))

    bg.add_task(_run_compile_in_thread)
    return {
        "task_id": task_id,
        "status": "queued",
        "book_id": book_id,
        "episode": episode,
        "shot_id": _coerce_storyboard_shot_id(shot_id),
        "compile_reason": req.compile_reason,
    }


@app.get("/api/storyboard-prompt-compile-tasks/{task_id}")
def get_storyboard_prompt_compile_task(task_id: str):
    task = _storyboard_prompt_compile_tasks.get(task_id)
    if not task:
        raise HTTPException(status_code=404, detail="Task not found")
    return task


@app.patch("/api/books/{book_id}/storyboard/{episode}/{shot_id}/prompt-lock")
def set_storyboard_prompt_lock(book_id: int, episode: int, shot_id: str, req: StoryboardPromptLockRequest):
    from models import Session, StoryboardShot

    with Session() as s:
        shot = s.query(StoryboardShot).filter(
            StoryboardShot.book_id == book_id,
            StoryboardShot.episode == episode,
            StoryboardShot.shot_id == _coerce_storyboard_shot_id(shot_id),
        ).first()
        if not shot:
            raise HTTPException(status_code=404, detail="Storyboard shot not found")

        shot_meta = safe_json_loads(shot.meta_info) if shot.meta_info else {}
        if not isinstance(shot_meta, dict):
            shot_meta = {}
        prompt_compiler_meta = shot_meta.get("prompt_compiler", {}) if isinstance(shot_meta.get("prompt_compiler", {}), dict) else {}
        prompt_compiler_meta["locked"] = req.locked
        if req.locked:
            prompt_compiler_meta["locked_version"] = prompt_compiler_meta.get("latest_version")
        else:
            prompt_compiler_meta["locked_version"] = None
        shot_meta["prompt_compiler"] = prompt_compiler_meta
        shot.meta_info = json.dumps(shot_meta, ensure_ascii=False)
        shot.updated_at = datetime.utcnow()
        s.commit()

        return {
            "book_id": book_id,
            "episode": episode,
            "shot_id": shot.shot_id,
            "locked": bool(prompt_compiler_meta.get("locked")),
            "locked_version": prompt_compiler_meta.get("locked_version"),
        }


async def _queue_storyboard_generation_task(
    book_id: int,
    episode: int,
    shot_id: str,
    kind: str,
    req: StoryboardGenerationRequest,
    bg: BackgroundTasks,
):
    from models import Session, StoryboardShot

    with Session() as s:
        shot = s.query(StoryboardShot).filter(
            StoryboardShot.book_id == book_id,
            StoryboardShot.episode == episode,
            StoryboardShot.shot_id == _coerce_storyboard_shot_id(shot_id),
        ).first()
        if not shot:
            raise HTTPException(status_code=404, detail="Storyboard shot not found")

        if req.compile_if_missing and (not shot.visual_prompt_static or not shot.visual_prompt_motion):
            raise HTTPException(status_code=409, detail={
                "message": "当前镜头缺少提示词；系统不会为生成任务自动调用 LLM。请先在受控 Prompt Compiler 草案中审核并创建版本。",
                "requires_prompt_draft": True,
                "generation_not_started": True,
            })

        prompt = (shot.visual_prompt_static if kind == "image" else shot.visual_prompt_motion or "").strip()
        if not prompt:
            raise HTTPException(status_code=400, detail="Storyboard prompts are empty. Compile prompts first.")

        executability: dict[str, Any] = {}
        if kind == "video":
            shot_meta_for_gate = safe_json_loads(shot.meta_info) if shot.meta_info else {}
            if not isinstance(shot_meta_for_gate, dict):
                shot_meta_for_gate = {}
            structured_for_gate = shot_meta_for_gate.get("structured_shot", {}) if isinstance(shot_meta_for_gate.get("structured_shot", {}), dict) else {}
            compiler_for_gate = shot_meta_for_gate.get("prompt_compiler", {}) if isinstance(shot_meta_for_gate.get("prompt_compiler", {}), dict) else {}
            context_for_gate = compiler_for_gate.get("prompt_compile_context", {}) if isinstance(compiler_for_gate.get("prompt_compile_context", {}), dict) else {}
            candidate = context_for_gate.get("executability") or structured_for_gate.get("executability") or {}
            executability = candidate if isinstance(candidate, dict) else {}
            exec_status = str(executability.get("status") or "").strip().lower()
            if not exec_status:
                raise HTTPException(status_code=409, detail={
                    "message": "当前镜头尚未完成可拍性校验，请先重新编译提示词后再生成视频。",
                    "executability": {"status": "blocked", "blocking_issues": ["missing-executability-result"]},
                    "requires_recompile": True,
                })
            if exec_status == "blocked":
                raise HTTPException(status_code=409, detail={
                    "message": "当前镜头可拍性校验为 blocked，不能提交视频生成。请延长、删减或拆分镜头后重新编译。",
                    "executability": executability,
                    "requires_recompile": True,
                })
            if exec_status == "warning" and not req.executability_override:
                raise HTTPException(status_code=409, detail={
                    "message": "当前镜头可拍性校验存在 warning。请确认仍要提交，或先按建议优化镜头。",
                    "executability": executability,
                    "requires_confirmation": True,
                })
            if exec_status == "warning" and req.executability_override:
                audit = shot_meta_for_gate.get("executability_overrides", [])
                if not isinstance(audit, list):
                    audit = []
                audit.append({
                    "at": datetime.utcnow().isoformat(),
                    "reason": str(req.executability_override_reason or "operator-confirmed-warning").strip(),
                    "status": exec_status,
                    "action": "video-generation",
                })
                shot_meta_for_gate["executability_overrides"] = audit[-20:]
                shot.meta_info = json.dumps(shot_meta_for_gate, ensure_ascii=False)
                shot.updated_at = datetime.utcnow()

        negative_prompt = (shot.visual_prompt_final or "").strip()
        asset_links = _load_asset_links(shot.asset_links)
        first_frame_asset_id = ""
        first_frame_url = ""
        if kind == "video":
            video_context = _resolve_storyboard_video_generation_context(shot, req)
            asset_links = video_context["asset_links"]
            reference_asset_ids = video_context["reference_asset_ids"]
            reference_images = video_context["reference_images"]
            first_frame_asset_id = video_context["first_frame_asset_id"]
            first_frame_url = video_context["first_frame_url"]
        else:
            reference_asset_ids, reference_images = _resolve_storyboard_reference_payloads(shot, req.reference_asset_ids)

        task_id = uuid.uuid4().hex[:12]
        creative_req = CreativeGenerationRequest(
            book_id=book_id,
            episode=episode,
            shot_id=str(shot.shot_id),
            source_node_id=f"production-shot-{episode}-{shot.shot_id}",
            source_asset_id=first_frame_asset_id,
            first_frame_asset_id=first_frame_asset_id,
            first_frame_url=first_frame_url,
            asset_scope="shot",
            asset_subject=str(shot.shot_id),
            target_kind=kind,
            prompt=prompt,
            negative_prompt=negative_prompt,
            model_profile_id=req.model_profile_id,
            reference_asset_ids=reference_asset_ids,
            reference_images=reference_images,
            aspect_ratio=req.aspect_ratio,
            duration_seconds=req.duration_seconds or int(getattr(shot, "duration", None) or 5),
            confirmed=req.confirmed,
            allow_external_call=req.allow_external_call,
        )

        try:
            profile = _resolve_creative_profile(creative_req, "image" if kind == "image" else "video")
        except (ModelProfileError, ValueError) as exc:
            raise HTTPException(status_code=400, detail=str(exc)) from exc
        _ensure_external_generation_confirmation(
            profile,
            creative_req,
            capability="image" if kind == "image" else "video",
        )

        continuity_policy: dict[str, Any] = {}
        if kind == "video":
            continuity_policy = _resolve_storyboard_video_continuity_policy(s, shot, profile, reference_images)
            if continuity_policy.get("blocking_issues"):
                raise HTTPException(
                    status_code=409,
                    detail={
                        "message": "已确认的镜头连续性合约无法由当前模型/交接帧满足，未提交生成。",
                        "continuity": continuity_policy,
                        "requires_operator_action": True,
                    },
                )
            if continuity_policy.get("strategy") == "strict_first_frame":
                locked_frame = continuity_policy.get("transition_frame") or {}
                first_frame_asset_id = f"transition-frame-{locked_frame.get('id')}"
                first_frame_url = str(continuity_policy.get("first_frame_url") or "").strip()
                reference_asset_ids = []
                reference_images = []
                creative_req = creative_req.model_copy(update={
                    "source_asset_id": first_frame_asset_id,
                    "first_frame_asset_id": first_frame_asset_id,
                    "first_frame_url": first_frame_url,
                    "reference_asset_ids": [],
                    "reference_images": [],
                })

        prompt_source = "storyboard_static" if kind == "image" else "storyboard_motion"
        source_duration_seconds = int(req.duration_seconds or getattr(shot, "duration", None) or 5)
        effective_duration_seconds = source_duration_seconds
        if kind == "video" and str(profile.get("provider") or "").strip() in {MINIMAX_H3_ASYNC_PROVIDER, MINIMAX_H3_75API_PROVIDER}:
            # A strict handoff uses the locked predecessor frame as H3's sole
            # visual input.  H3 does not support keyframe and reference-image
            # modes together, so its exported prompt must not claim numbered
            # references that the provider request deliberately omits.
            if continuity_policy.get("strategy") == "strict_first_frame":
                h3_reference_images: list[dict[str, Any]] = []
            else:
                _, h3_reference_images = _resolve_storyboard_video_reference_payloads(
                    shot,
                    creative_req.reference_asset_ids,
                    max_reference_images=_model_max_reference_images(profile),
                )
            h3_preview = _preview_storyboard_machine_prompt_export(
                book_id,
                shot,
                "minimax-h3",
                reference_images_override=h3_reference_images,
            )
            h3_export = (
                h3_preview.get("model_exports", {}).get("minimax-h3", {})
                if isinstance(h3_preview.get("model_exports", {}), dict)
                else {}
            )
            h3_fields = h3_export.get("fields", {}) if isinstance(h3_export, dict) else {}
            h3_prompt = str(h3_fields.get("integrated_multimodal_description") or "").strip()
            if not h3_prompt:
                raise HTTPException(status_code=409, detail="MiniMax H3 机器提示词编译失败，请先重新编译镜头提示词。")
            h3_prompt = _append_video_continuity_contract_to_prompt(h3_prompt, continuity_policy)
            if str(profile.get("provider") or "").strip() == MINIMAX_H3_75API_PROVIDER:
                try:
                    effective_duration_seconds = normalize_75api_minimax_h3_seconds(source_duration_seconds)
                except ModelProfileError as exc:
                    raise HTTPException(status_code=409, detail=str(exc)) from exc
            else:
                effective_duration_seconds = normalize_minimax_h3_duration(source_duration_seconds)
            creative_req = creative_req.model_copy(update={
                "prompt": h3_prompt,
                "duration_seconds": effective_duration_seconds,
            })
            prompt_source = "minimax_h3_machine_export"
        first_frame_public_asset: dict[str, Any] = {}
        reference_public_assets: list[dict[str, Any]] = []
        if kind == "video" and str(profile.get("provider") or "").strip() != "prototype-task-adapter":
            if continuity_policy.get("strategy") == "strict_first_frame":
                # The registered transition frame is required to be public when
                # it is written. Never replace it with this shot's references.
                reference_asset_ids, reference_images = [], []
            elif creative_req.reference_images:
                reference_asset_ids, reference_images, reference_public_assets = _resolve_provider_ready_storyboard_reference_images(
                    shot,
                    requested_reference_asset_ids=creative_req.reference_asset_ids,
                    max_reference_images=_model_max_reference_images(profile),
                    include_composition_reference=True,
                    allow_unstable_storage=req.allow_unstable_public_assets,
                )
                first_frame_asset_id = ""
                first_frame_url = ""
            else:
                first_frame_asset_id, first_frame_url, first_frame_public_asset = _resolve_provider_ready_storyboard_first_frame(
                    shot,
                    first_frame_asset_id=req.first_frame_asset_id,
                    allow_unstable_storage=req.allow_unstable_public_assets,
                )
            creative_req = creative_req.model_copy(update={
                "source_asset_id": first_frame_asset_id or None,
                "first_frame_asset_id": first_frame_asset_id or None,
                "first_frame_url": first_frame_url or None,
                "reference_asset_ids": reference_asset_ids,
                "reference_images": reference_images,
            })

        _creative_tasks[task_id] = {
            "task_id": task_id,
            "status": "queued",
            "progress": 0,
            "target_kind": kind,
            "book_id": book_id,
            "episode": episode,
            "shot_id": str(shot.shot_id),
            "version": _next_asset_version(book_id, episode, str(shot.shot_id), kind),
            "model_profile_id": profile.get("id"),
            "provider": profile.get("provider"),
            "uses_mock": profile.get("provider") == "prototype-task-adapter",
            "prompt_version": safe_json_loads(shot.meta_info).get("prompt_compiler", {}).get("latest_version") if shot.meta_info else None,
            "prompt_source": prompt_source,
            "source_duration_seconds": source_duration_seconds,
            "effective_duration_seconds": effective_duration_seconds,
            "negative_prompt": negative_prompt,
            "first_frame_asset_id": first_frame_asset_id,
            "first_frame_url": first_frame_url,
            "first_frame_public_asset": first_frame_public_asset,
            "reference_asset_ids": reference_asset_ids,
            "reference_images": reference_images,
            "reference_public_assets": reference_public_assets,
            "continuity": continuity_policy,
            "provider_task_mode": "reference_to_video" if kind == "video" and reference_asset_ids else ("image_to_video" if kind == "video" and first_frame_asset_id else "text_to_video" if kind == "video" else ""),
            "external_task_id": None,
            "external_status": None,
            "poll_attempts": 0,
            "provider_response": None,
            "provider_request_payload": None,
            "generation_chain": (req.generation_chain or "").strip() or None,
            "triggered_by_prompt_recompile": bool(req.triggered_by_prompt_recompile),
            "prompt_recompile_reason": (req.prompt_recompile_reason or "").strip() or None,
            "prompt_recompile_task_id": (req.prompt_recompile_task_id or "").strip() or None,
            "prompt_recompile_version": req.prompt_recompile_version,
            "executability": executability,
            "executability_override": bool(req.executability_override),
            "executability_override_reason": (req.executability_override_reason or "").strip() or None,
            "allow_unstable_public_assets": bool(req.allow_unstable_public_assets),
            "unstable_public_asset_override": bool(
                any(
                    isinstance(item, dict) and item.get("unstable_storage_override")
                    for item in reference_public_assets
                )
                or (isinstance(first_frame_public_asset, dict) and first_frame_public_asset.get("unstable_storage_override"))
            ),
            "external_call_confirmed": bool(req.confirmed and req.allow_external_call),
        }
        _store_creative_task_request(_creative_tasks[task_id], creative_req, kind)
        if req.generation_chain or req.triggered_by_prompt_recompile or req.prompt_recompile_task_id or req.prompt_recompile_version is not None:
            request_payload = _creative_tasks[task_id].get("request_payload")
            if isinstance(request_payload, dict):
                request_payload["generation_chain"] = (req.generation_chain or "").strip() or None
                request_payload["triggered_by_prompt_recompile"] = bool(req.triggered_by_prompt_recompile)
                request_payload["prompt_recompile_reason"] = (req.prompt_recompile_reason or "").strip() or None
                request_payload["prompt_recompile_task_id"] = (req.prompt_recompile_task_id or "").strip() or None
                request_payload["prompt_recompile_version"] = req.prompt_recompile_version
        request_payload = _creative_tasks[task_id].get("request_payload")
        if isinstance(request_payload, dict):
            request_payload["first_frame_public_asset"] = first_frame_public_asset
            request_payload["reference_public_assets"] = reference_public_assets
            request_payload["continuity"] = continuity_policy
            request_payload["allow_unstable_public_assets"] = bool(req.allow_unstable_public_assets)
            request_payload["unstable_public_asset_override"] = bool(
                any(
                    isinstance(item, dict) and item.get("unstable_storage_override")
                    for item in reference_public_assets
                )
                or (isinstance(first_frame_public_asset, dict) and first_frame_public_asset.get("unstable_storage_override"))
            )
        s.commit()

    bg.add_task(_run_creative_task, task_id, kind, creative_req)
    return {
        "task_id": task_id,
        "status": "queued",
        "prompt": creative_req.prompt,
        "negative_prompt": negative_prompt,
        "first_frame_asset_id": first_frame_asset_id,
        "first_frame_url": first_frame_url,
        "reference_asset_ids": reference_asset_ids,
        "reference_images": reference_images,
        "model_profile_id": profile.get("id"),
        "uses_mock": profile.get("provider") == "prototype-task-adapter",
        "continuity": continuity_policy,
    }


@app.post("/api/books/{book_id}/storyboard/{episode}/{shot_id}/generate-frame")
async def generate_storyboard_frame(book_id: int, episode: int, shot_id: str, req: StoryboardGenerationRequest, bg: BackgroundTasks):
    return await _queue_storyboard_generation_task(book_id, episode, shot_id, "image", req, bg)


@app.post("/api/books/{book_id}/storyboard/{episode}/{shot_id}/generate-video")
async def generate_storyboard_video(book_id: int, episode: int, shot_id: str, req: StoryboardGenerationRequest, bg: BackgroundTasks):
    return await _queue_storyboard_generation_task(book_id, episode, shot_id, "video", req, bg)


@app.get("/api/books/{book_id}/storyboard/{episode}/{shot_id}/acceptance-records")
def get_storyboard_acceptance_records(book_id: int, episode: int, shot_id: str):
    from models import Session, StoryboardAcceptanceRecord

    coerced_shot_id = _coerce_storyboard_shot_id(shot_id)
    with Session() as s:
        rows = s.query(StoryboardAcceptanceRecord).filter(
            StoryboardAcceptanceRecord.book_id == book_id,
            StoryboardAcceptanceRecord.episode == episode,
            StoryboardAcceptanceRecord.shot_id == coerced_shot_id,
        ).order_by(StoryboardAcceptanceRecord.created_at.desc(), StoryboardAcceptanceRecord.id.desc()).all()
        return {
            "book_id": book_id,
            "episode": episode,
            "shot_id": coerced_shot_id,
            "records": [
                {
                    "id": row.id,
                    "asset_kind": row.asset_kind,
                    "asset_id": row.asset_id,
                    "status": row.status,
                    "failure_tags": _json_loads_list(row.failure_tags),
                    "notes": row.notes,
                    "meta_info": safe_json_loads(row.meta_info) if row.meta_info else {},
                    "created_at": row.created_at.isoformat() if row.created_at else None,
                    "updated_at": row.updated_at.isoformat() if row.updated_at else None,
                }
                for row in rows
            ],
        }


@app.post("/api/books/{book_id}/storyboard/{episode}/{shot_id}/acceptance-records")
def create_storyboard_acceptance_record(book_id: int, episode: int, shot_id: str, req: StoryboardAcceptanceRequest):
    from models import (
        Session,
        StoryboardAcceptanceRecord,
        StoryboardShot,
        StoryboardTransitionContract,
        StoryboardTransitionContinuityReview,
        StoryboardTransitionFrame,
    )

    now = datetime.utcnow()
    coerced_shot_id = _coerce_storyboard_shot_id(shot_id)
    with Session() as s:
        shot = s.query(StoryboardShot).filter(
            StoryboardShot.book_id == book_id,
            StoryboardShot.episode == episode,
            StoryboardShot.shot_id == coerced_shot_id,
        ).first()
        if not shot:
            raise HTTPException(status_code=404, detail="Storyboard shot not found")

        # A strict continuity target cannot be marked accepted before its
        # locked handoff frame has a reviewed, passing comparison.  Previously
        # the acceptance endpoint allowed a manual "passed" status to bypass
        # the continuity audit entirely, which let composition drift reach
        # production.  This gate is contract-driven and applies to every
        # strict pair, not to a particular book or shot.
        accepted_statuses = {"passed", "approved", "accepted"}
        if str(req.asset_kind or "").strip().lower() == "video" and str(req.status or "").strip().lower() in accepted_statuses:
            strict_contract = s.query(StoryboardTransitionContract).filter(
                StoryboardTransitionContract.book_id == book_id,
                StoryboardTransitionContract.episode == episode,
                StoryboardTransitionContract.target_shot_id == coerced_shot_id,
                StoryboardTransitionContract.status == "confirmed",
                StoryboardTransitionContract.continuity_level == "strict",
            ).order_by(StoryboardTransitionContract.version.desc(), StoryboardTransitionContract.id.desc()).first()
            if strict_contract:
                handoff = s.query(StoryboardTransitionFrame).filter(
                    StoryboardTransitionFrame.book_id == book_id,
                    StoryboardTransitionFrame.episode == episode,
                    StoryboardTransitionFrame.target_shot_id == coerced_shot_id,
                    StoryboardTransitionFrame.status == "locked",
                ).order_by(StoryboardTransitionFrame.id.desc()).first()
                passing_review = None
                if handoff:
                    passing_review = s.query(StoryboardTransitionContinuityReview).filter(
                        StoryboardTransitionContinuityReview.book_id == book_id,
                        StoryboardTransitionContinuityReview.episode == episode,
                        StoryboardTransitionContinuityReview.target_shot_id == coerced_shot_id,
                        StoryboardTransitionContinuityReview.transition_frame_id == handoff.id,
                        StoryboardTransitionContinuityReview.target_video_asset_id == str(req.asset_id or "").strip(),
                        StoryboardTransitionContinuityReview.status == "reviewed",
                        StoryboardTransitionContinuityReview.review_result == "pass",
                    ).order_by(StoryboardTransitionContinuityReview.id.desc()).first()
                if not passing_review:
                    raise HTTPException(
                        status_code=409,
                        detail={
                            "message": "严格连续性镜头必须先完成交接帧对比验收，且结果为通过，才能标记视频合格。",
                            "requires_continuity_review": True,
                            "transition_frame_id": int(handoff.id) if handoff else None,
                            "target_video_asset_id": str(req.asset_id or "").strip(),
                        },
                    )

        row = StoryboardAcceptanceRecord(
            book_id=book_id,
            episode=episode,
            shot_id=coerced_shot_id,
            asset_kind=req.asset_kind,
            asset_id=req.asset_id,
            status=req.status,
            failure_tags=json.dumps([tag for tag in req.failure_tags if str(tag).strip()], ensure_ascii=False),
            notes=req.notes,
            meta_info=json.dumps(req.meta_info, ensure_ascii=False),
            created_at=now,
            updated_at=now,
        )
        s.add(row)

        shot_meta = safe_json_loads(shot.meta_info) if shot.meta_info else {}
        if not isinstance(shot_meta, dict):
            shot_meta = {}
        shot_meta["acceptance"] = {
            "status": req.status,
            "asset_kind": req.asset_kind,
            "asset_id": req.asset_id,
            "failure_tags": [tag for tag in req.failure_tags if str(tag).strip()],
            "notes": req.notes,
            "updated_at": now.isoformat(),
        }
        shot.meta_info = json.dumps(shot_meta, ensure_ascii=False)
        shot.updated_at = now
        s.commit()
        s.refresh(row)

        return {
            "id": row.id,
            "asset_kind": row.asset_kind,
            "asset_id": row.asset_id,
            "status": row.status,
            "failure_tags": _json_loads_list(row.failure_tags),
            "notes": row.notes,
            "meta_info": safe_json_loads(row.meta_info) if row.meta_info else {},
            "created_at": row.created_at.isoformat() if row.created_at else None,
            "updated_at": row.updated_at.isoformat() if row.updated_at else None,
        }


def _normalize_export_format_label(value: str) -> str:
    normalized = str(value or "").strip().lower()
    if not normalized:
        return "JSON"
    if normalized == "pdf":
        return "PDF"
    if normalized == "json":
        return "JSON"
    if normalized == "delivery":
        return "交付快照"
    return normalized.upper()


def _looks_corrupted_export_text(value: str) -> bool:
    text = str(value or "").strip()
    if not text:
        return False
    if text == "[object Object]":
        return True
    if "????" in text or "锟" in text:
        return True
    if "manual verification snapshot" in text.lower():
        return True
    if " 璺" in text:
        return True
    return any(token in text for token in ["閸", "闂", "鐠", "缁", "瀵板懘", "閺堫亝"])


def _normalize_export_record_summary(row, meta_info: dict) -> str:
    raw_summary = str(getattr(row, "summary", "") or "").strip()
    if raw_summary and not _looks_corrupted_export_text(raw_summary):
        return raw_summary

    episode = int(meta_info.get("episode") or 0)
    format_label = _normalize_export_format_label(getattr(row, "export_format", ""))
    blocked_reasons = meta_info.get("blocked_reasons", [])
    if not isinstance(blocked_reasons, list):
        blocked_reasons = []
    blocked_reasons = [str(item).strip() for item in blocked_reasons if str(item).strip()]
    blocked_reasons = [item for item in blocked_reasons if not _looks_corrupted_export_text(item)]
    if not blocked_reasons:
        legacy_issues = meta_info.get("issues", [])
        if isinstance(legacy_issues, list):
            blocked_reasons = [
                str(item).strip()
                for item in legacy_issues
                if str(item).strip() and not _looks_corrupted_export_text(str(item))
            ]
    if not blocked_reasons and int(getattr(row, "blocked_shots", 0) or 0) > 0:
        blocked_reasons = [f"历史阻塞镜头 {int(getattr(row, 'blocked_shots', 0) or 0)} 个，待补录明细"]

    script_status = str(meta_info.get("script_status") or "").strip()
    if not script_status:
        script_locked = bool(meta_info.get("script_locked"))
        script_released = bool(meta_info.get("script_released"))
        if script_locked and script_released:
            script_status = "已锁稿并放行"
        elif script_locked:
            script_status = "待放行"
        elif "script_locked" in meta_info or "script_released" in meta_info:
            script_status = "待锁稿"

    parts: list[str] = []
    if episode > 0:
        parts.append(f"第 {episode} 集")
    if script_status:
        parts.append(f"剧本 {script_status}")
    parts.append(
        f"可交付镜头 {int(getattr(row, 'deliverable_shots', 0) or 0)}/{int(getattr(row, 'total_shots', 0) or 0)}"
    )

    pending_review_shots = int(getattr(row, "pending_review_shots", 0) or 0)
    if pending_review_shots > 0:
        parts.append(f"待复核 {pending_review_shots}")

    if blocked_reasons:
        parts.append(" / ".join(blocked_reasons[:3]))
    else:
        parts.append("已登记交付版本" if getattr(row, "status", "") == "completed" else f"{format_label} 快照")

    return " | ".join(parts)


def _serialize_production_export_record(row) -> dict:
    meta_info = safe_json_loads(row.meta_info) if row.meta_info else {}
    if not isinstance(meta_info, dict):
        meta_info = {}
    return {
        "id": row.id,
        "book_id": row.book_id,
        "export_format": row.export_format,
        "format_label": _normalize_export_format_label(getattr(row, "export_format", "")),
        "status": row.status,
        "total_shots": row.total_shots,
        "deliverable_shots": row.deliverable_shots,
        "pending_review_shots": row.pending_review_shots,
        "blocked_shots": row.blocked_shots,
        "summary": _normalize_export_record_summary(row, meta_info),
        "meta_info": meta_info,
        "created_at": row.created_at.isoformat() if row.created_at else None,
        "updated_at": row.updated_at.isoformat() if row.updated_at else None,
    }


def _get_production_export_record_asset_type(record: dict) -> str:
    meta_info = record.get("meta_info") if isinstance(record.get("meta_info"), dict) else {}
    record_type = str(meta_info.get("record_type") or "").strip()
    export_format = str(record.get("export_format") or "").strip()
    if record_type == "storyboard_machine_prompt_export" or export_format.startswith("storyboard-machine-prompt-"):
        return "machine_prompt"
    return "delivery_package"


def _production_export_record_matches_record_type(record: dict, record_type_filter: str | None) -> bool:
    record_type_filter = str(record_type_filter or "").strip().lower()
    if not record_type_filter or record_type_filter == "all":
        return True
    meta_info = record.get("meta_info") if isinstance(record.get("meta_info"), dict) else {}
    meta_record_type = str(meta_info.get("record_type") or "").strip().lower()
    asset_type = _get_production_export_record_asset_type(record)
    if record_type_filter in {"machine_prompt", "delivery_package"}:
        return asset_type == record_type_filter
    return meta_record_type == record_type_filter


def _production_export_record_matches_format(record: dict, format_filter: str | None) -> bool:
    format_filter = str(format_filter or "").strip().lower()
    if not format_filter or format_filter == "all":
        return True
    export_format = str(record.get("export_format") or "").strip().lower()
    format_label = str(record.get("format_label") or "").strip().lower()
    normalized_filter_label = _normalize_export_format_label(format_filter).lower()
    return format_filter in {export_format, format_label} or normalized_filter_label == format_label


def _build_production_export_record_search_text(record: dict) -> str:
    meta_info = record.get("meta_info") if isinstance(record.get("meta_info"), dict) else {}
    search_items = [
        record.get("id"),
        record.get("episode"),
        record.get("status"),
        record.get("export_format"),
        record.get("format_label"),
        record.get("summary"),
        meta_info.get("record_type"),
        meta_info.get("target_model"),
        meta_info.get("export_channel"),
        meta_info.get("scene_name"),
        meta_info.get("episode"),
        meta_info.get("shot_id"),
        meta_info.get("director_shot_text"),
    ]
    for key in ("blocked_reasons", "blockedReasons", "issues", "warnings"):
        value = meta_info.get(key)
        if isinstance(value, list):
            search_items.extend(value)
        elif value:
            search_items.append(value)
    return " ".join(str(item or "").lower() for item in search_items)


def _production_export_record_matches_query(record: dict, query_text: str | None) -> bool:
    terms = [term for term in str(query_text or "").strip().lower().split() if term]
    if not terms:
        return True
    search_text = _build_production_export_record_search_text(record)
    return all(term in search_text for term in terms)


def _production_export_record_matches_filters(
    record: dict,
    *,
    record_type: str | None,
    episode: int | None,
    status: str | None,
    export_format: str | None,
    query_text: str | None,
) -> bool:
    meta_info = record.get("meta_info") if isinstance(record.get("meta_info"), dict) else {}
    if episode is not None:
        try:
            record_episode = int(meta_info.get("episode") or 0)
        except (TypeError, ValueError):
            record_episode = 0
        if record_episode != episode:
            return False

    status_filter = str(status or "").strip().lower()
    if status_filter and status_filter != "all" and str(record.get("status") or "").strip().lower() != status_filter:
        return False

    if not _production_export_record_matches_record_type(record, record_type):
        return False
    if not _production_export_record_matches_format(record, export_format):
        return False
    if not _production_export_record_matches_query(record, query_text):
        return False
    return True


def _is_storyboard_shot_deliverable_for_export(shot) -> bool:
    asset_links = _load_asset_links(getattr(shot, "asset_links", None))
    adopted_video = _find_adopted_shot_asset(asset_links, "videos")
    meta_info = safe_json_loads(getattr(shot, "meta_info", None)) if getattr(shot, "meta_info", None) else {}
    acceptance = meta_info.get("acceptance", {}) if isinstance(meta_info, dict) else {}
    acceptance_status = str(acceptance.get("status") or "").strip().lower()
    # The acceptance-record API uses ``passed`` as its successful QA result,
    # while legacy export data used ``approved``/``accepted``.  All three
    # represent a reviewed, positive acceptance; treating one of them as
    # non-deliverable breaks downstream transition evidence and export gates.
    return bool(adopted_video) and acceptance_status in {"passed", "approved", "accepted"}


def _build_export_shot_payload(shot) -> dict:
    asset_links = _load_asset_links(getattr(shot, "asset_links", None))
    meta_info = safe_json_loads(getattr(shot, "meta_info", None)) if getattr(shot, "meta_info", None) else {}
    acceptance = meta_info.get("acceptance", {}) if isinstance(meta_info, dict) else {}
    prompt_compiler = meta_info.get("prompt_compiler", {}) if isinstance(meta_info, dict) else {}
    reference_summary = _build_storyboard_reference_summary(asset_links, str(getattr(shot, "scene_name", "") or "").strip())
    adopted_image = _find_adopted_shot_asset(asset_links, "images") or {}
    adopted_video = _find_adopted_shot_asset(asset_links, "videos") or {}

    return {
        "episode": getattr(shot, "episode", ""),
        "shot_id": getattr(shot, "shot_id", ""),
        "scene_name": str(getattr(shot, "scene_name", "") or ""),
        "camera_angle": str(getattr(shot, "camera_angle", "") or ""),
        "camera_movement": str(getattr(shot, "camera_movement", "") or ""),
        "camera_speed": str(getattr(shot, "camera_speed", "") or ""),
        "shot_purpose": str(getattr(shot, "shot_purpose", "") or ""),
        "emotion_arc": safe_json_loads(getattr(shot, "emotion_arc", "{}"), {}),
        "duration": str(getattr(shot, "duration", "") or ""),
        "dialogue": str(getattr(shot, "dialogue", "") or ""),
        "action_process": str(getattr(shot, "action_process", "") or ""),
        "prompt_version": prompt_compiler.get("latest_version") or "",
        "acceptance_status": str(acceptance.get("status") or ""),
        "acceptance_notes": str(acceptance.get("notes") or ""),
        "adopted_image_title": str(adopted_image.get("title") or adopted_image.get("id") or ""),
        "adopted_video_title": str(adopted_video.get("title") or adopted_video.get("id") or ""),
        "reference_summary_text": str(reference_summary.get("summary_text") or ""),
        "reference_count": int((reference_summary.get("counts") or {}).get("total") or 0),
    }


def _serialize_storyboard_output_row(
    s,
    book_id: int,
    shot,
    locations: list,
    makeups: list,
    reference_index: dict[tuple[str, str], list[dict]],
) -> dict:
    payload = {
        "episode": shot.episode,
        "shot_id": shot.shot_id,
        "scene_name": shot.scene_name,
        "dialogue": shot.dialogue,
        "duration": shot.duration,
        "camera_angle": shot.camera_angle,
        "camera_movement": shot.camera_movement,
        "camera_speed": shot.camera_speed,
        "shot_purpose": shot.shot_purpose,
        "emotion_arc": safe_json_loads(shot.emotion_arc, {}),
        "transition": shot.transition,
        "lighting": shot.lighting,
        "sound_effects": __import__("json").loads(shot.sound_effects)
        if isinstance(shot.sound_effects, str) and shot.sound_effects.startswith("[")
        else [],
        "bgm_mood": shot.bgm_mood,
        "start_state": shot.start_state,
        "action_process": shot.action_process,
        "end_state": shot.end_state,
        "visual_prompt_static": shot.visual_prompt_static,
        "visual_prompt_motion": shot.visual_prompt_motion,
        "visual_prompt_final": shot.visual_prompt_final,
        "makeup_prompts": [
            {
                "character_name": m.character_name,
                "refined_outfit": m.refined_outfit,
                "refined_accessories": m.refined_accessories,
                "makeup_spec": m.makeup_spec,
                "hair_style": m.hair_style,
                "visual_prompt_zh": m.visual_prompt_zh,
            }
            for m in (__import__("copy").copy(makeups))
            if m.episode == shot.episode
        ],
    }
    sanitized_asset_links = (
        _sanitize_storyboard_asset_links(safe_json_loads(shot.asset_links), shot.scene_name)
        if shot.asset_links else {}
    )
    meta_info = safe_json_loads(shot.meta_info) if shot.meta_info else {}
    if not isinstance(meta_info, dict):
        meta_info = {}
    structured_shot = _auto_bind_structured_shot_assets(
        book_id,
        shot.episode,
        _derive_structured_shot_payload(meta_info, payload),
        payload,
    )
    prompt_compiler_meta = meta_info.get("prompt_compiler", {}) if isinstance(meta_info.get("prompt_compiler", {}), dict) else {}
    prompt_compiler_meta = _refresh_legacy_prompt_compile_meta(
        book_id,
        shot,
        structured_shot,
        prompt_compiler_meta,
    )
    acceptance_meta = meta_info.get("acceptance", {}) if isinstance(meta_info.get("acceptance", {}), dict) else {}
    prompt_compile_context = (
        prompt_compiler_meta.get("prompt_compile_context", {})
        if isinstance(prompt_compiler_meta.get("prompt_compile_context", {}), dict)
        else {}
    )
    scene_binding = (
        prompt_compile_context.get("asset_bindings", {}).get("scene", {})
        if isinstance(prompt_compile_context.get("asset_bindings", {}), dict)
        else {}
    )
    if not isinstance(scene_binding, dict):
        scene_binding = {}
    resolved_scene_name = (
        str(scene_binding.get("asset_name") or "").strip()
        or str(structured_shot.get("scene_name") or "").strip()
        or str(structured_shot.get("scene") or "").strip()
        or str(shot.scene_name or "").strip()
    )
    locked_reference_summary = prompt_compiler_meta.get("locked_reference_summary", {})
    has_locked_summary_content = (
        isinstance(locked_reference_summary, dict)
        and (
            bool(str(locked_reference_summary.get("summary_text") or "").strip())
            or bool(locked_reference_summary.get("scene"))
            or bool(locked_reference_summary.get("characters"))
            or bool(locked_reference_summary.get("props"))
            or bool(locked_reference_summary.get("all"))
        )
    )
    if not has_locked_summary_content:
        locked_reference_summary = _build_storyboard_reference_summary(
            sanitized_asset_links,
            resolved_scene_name,
        )
    prompt_version_audit = _build_storyboard_prompt_version_audit(prompt_compiler_meta)
    recommended_restore_version = None
    if prompt_compiler_meta.get("latest_version"):
        version_payloads = _build_storyboard_prompt_version_payloads(
            s,
            book_id,
            shot,
            prompt_compiler_meta.get("latest_version"),
            prompt_compiler_meta.get("locked_version"),
        )
        recommended_restore_version = _recommend_storyboard_restore_version(
            version_payloads,
            prompt_compiler_meta.get("latest_version"),
        )

    return {
        "episode": shot.episode,
        "shot_id": shot.shot_id,
        "scene_name": resolved_scene_name,
        "dialogue": shot.dialogue,
        "duration": shot.duration,
        "camera_angle": shot.camera_angle,
        "camera_movement": shot.camera_movement,
        "camera_speed": shot.camera_speed,
        "shot_purpose": shot.shot_purpose,
        "emotion_arc": safe_json_loads(shot.emotion_arc, {}),
        "transition": shot.transition,
        "lighting": shot.lighting,
        "sound_effects": payload["sound_effects"],
        "bgm_mood": shot.bgm_mood,
        "start_state": shot.start_state,
        "action_process": shot.action_process,
        "end_state": shot.end_state,
        "visual_prompt_static": shot.visual_prompt_static,
        "visual_prompt_motion": shot.visual_prompt_motion,
        "visual_prompt_final": shot.visual_prompt_final,
        "asset_links": sanitized_asset_links,
        "assets": {
            "images": sanitized_asset_links.get("images", []) if isinstance(sanitized_asset_links.get("images", []), list) else [],
            "videos": sanitized_asset_links.get("videos", []) if isinstance(sanitized_asset_links.get("videos", []), list) else [],
            "audios": sanitized_asset_links.get("audios", []) if isinstance(sanitized_asset_links.get("audios", []), list) else [],
        },
        "asset_status": shot.asset_status,
        "meta_info": meta_info,
        "structured_shot": structured_shot,
        "executability_split_draft": meta_info.get("executability_split_draft", {}) if isinstance(meta_info.get("executability_split_draft", {}), dict) else None,
        "negative_prompt": prompt_compiler_meta.get("negative_prompt", ""),
        "acceptance": acceptance_meta,
        "prompt_locked": bool(prompt_compiler_meta.get("locked", False)),
        "prompt_version": prompt_compiler_meta.get("latest_version"),
        "prompt_compile_context": prompt_compile_context,
        "used_assets": prompt_compiler_meta.get("used_assets", []),
        "reference_images": prompt_compiler_meta.get("reference_images", []),
        "reference_asset_ids": prompt_compiler_meta.get("reference_asset_ids", []),
        "compiler_warnings": prompt_compiler_meta.get("compiler_warnings", []),
        "compiler_diagnostics": prompt_compiler_meta.get("compiler_diagnostics", {}),
        "prompt_version_audit": prompt_version_audit,
        "recommended_restore_version": recommended_restore_version,
        "repair_attempted": bool(prompt_compiler_meta.get("repair_attempted", False)),
        "locked_reference_summary": locked_reference_summary,
        "makeup_prompts": _resolve_shot_makeup_payloads(
            s,
            book_id,
            shot,
            structured_shot,
            reference_index,
        ),
        "scene_prompt": (
            next(
                (
                    loc.visual_prompt_zh
                    or loc.core_prompt_zh
                    or ""
                )
                for loc in locations
                if loc.name == resolved_scene_name
            )
            if any(loc.name == resolved_scene_name for loc in locations)
            else ""
        ),
    }


def _build_production_export_pdf(book, scripts: list, storyboard_rows: list, summary: dict | None = None) -> bytes:
    try:
        from io import BytesIO
        from reportlab.lib import colors
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
        from reportlab.lib.units import mm
        from reportlab.pdfbase import pdfmetrics
        from reportlab.pdfbase.cidfonts import UnicodeCIDFont
        from reportlab.platypus import Paragraph, SimpleDocTemplate, Spacer, Table, TableStyle
    except ImportError as error:
        raise HTTPException(status_code=500, detail=f"PDF export dependency missing: {error}") from error

    pdfmetrics.registerFont(UnicodeCIDFont("STSong-Light"))
    styles = getSampleStyleSheet()
    title_style = ParagraphStyle("ExportTitle", parent=styles["Title"], fontName="STSong-Light", fontSize=18, leading=24)
    body_style = ParagraphStyle("ExportBody", parent=styles["BodyText"], fontName="STSong-Light", fontSize=10, leading=14)
    small_style = ParagraphStyle("ExportSmall", parent=styles["BodyText"], fontName="STSong-Light", fontSize=8, leading=11)

    buffer = BytesIO()
    doc = SimpleDocTemplate(buffer, pagesize=A4, leftMargin=15 * mm, rightMargin=15 * mm, topMargin=15 * mm, bottomMargin=15 * mm)
    export_summary = summary if isinstance(summary, dict) else {}
    total_shots = int(export_summary.get("total_shots") or len(storyboard_rows))
    deliverable_shots = int(export_summary.get("deliverable_shots") or len(storyboard_rows))
    blocked_shots = int(export_summary.get("blocked_shots") or max(total_shots - deliverable_shots, 0))
    story = [
        Paragraph(f"{book.title} Production Export", title_style),
        Spacer(1, 4 * mm),
        Paragraph(f"Export time: {datetime.utcnow().strftime('%Y-%m-%d %H:%M:%S')} UTC", body_style),
        Paragraph(f"Scripts: {len(scripts)} | Total shots: {total_shots}", body_style),
        Paragraph(f"Deliverable shots: {deliverable_shots} | Blocked shots: {blocked_shots}", body_style),
        Spacer(1, 6 * mm),
        Paragraph("Scripts", body_style),
        Spacer(1, 2 * mm),
    ]

    if scripts:
        for script in scripts:
            story.append(Paragraph(f"Episode {script.episode}", body_style))
            for line in str(script.content or "").splitlines():
                if line.strip():
                    story.append(Paragraph(line.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;"), small_style))
            story.append(Spacer(1, 4 * mm))
    else:
        story.append(Paragraph("No script content available", small_style))
        story.append(Spacer(1, 4 * mm))

    shot_payloads = [_build_export_shot_payload(shot) for shot in storyboard_rows[:200]]

    story.append(Paragraph("Storyboard Table (approved shots with adopted video only)", body_style))
    table_rows = [["Ep", "Shot", "Scene", "Camera", "Prompt", "Acceptance", "Adopted Video", "Refs"]]
    for shot in shot_payloads:
        table_rows.append([
            str(shot["episode"]),
            str(shot["shot_id"]),
            str(shot["scene_name"]),
            f'{shot["camera_angle"]}/{shot["camera_movement"]}'[:24],
            f'v{shot["prompt_version"]}' if shot["prompt_version"] else "-",
            str(shot["acceptance_status"] or "-"),
            str(shot["adopted_video_title"] or "-")[:28],
            str(shot["reference_count"]),
        ])

    if len(table_rows) == 1:
        table_rows.append(["-", "-", "No deliverable shots", "", "", "", "", ""])

    table = Table(table_rows, repeatRows=1, colWidths=[12 * mm, 14 * mm, 28 * mm, 16 * mm, 22 * mm, 14 * mm, 32 * mm, 42 * mm])
    table.setStyle(TableStyle([
        ("FONTNAME", (0, 0), (-1, -1), "STSong-Light"),
        ("FONTSIZE", (0, 0), (-1, -1), 8),
        ("LEADING", (0, 0), (-1, -1), 10),
        ("BACKGROUND", (0, 0), (-1, 0), colors.HexColor("#E2E8F0")),
        ("GRID", (0, 0), (-1, -1), 0.5, colors.HexColor("#CBD5E1")),
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, colors.HexColor("#F8FAFC")]),
    ]))
    story.append(table)
    story.append(Spacer(1, 5 * mm))
    story.append(Paragraph("Shot Delivery Details", body_style))

    if shot_payloads:
        for shot in shot_payloads:
            story.append(
                Paragraph(
                    f'E{shot["episode"]} / {shot["shot_id"]} / {shot["scene_name"] or "Unnamed scene"}',
                    body_style,
                )
            )
            story.append(
                Paragraph(
                    (
                        f'Camera: {shot["camera_angle"] or "-"} | Motion: {shot["camera_movement"] or "-"} | '
                        f'Duration: {shot["duration"] or "-"} | Prompt: {("v" + str(shot["prompt_version"])) if shot["prompt_version"] else "-"}'
                    ),
                    small_style,
                )
            )
            if shot["adopted_image_title"] or shot["adopted_video_title"]:
                story.append(
                    Paragraph(
                        f'Adopted frame: {shot["adopted_image_title"] or "-"} | Adopted video: {shot["adopted_video_title"] or "-"}',
                        small_style,
                    )
                )
            if shot["reference_summary_text"]:
                story.append(Paragraph(f'References: {shot["reference_summary_text"]}', small_style))
            if shot["dialogue"]:
                story.append(Paragraph(f'Dialogue: {shot["dialogue"][:160]}', small_style))
            if shot["action_process"]:
                story.append(Paragraph(f'Action: {shot["action_process"][:200]}', small_style))
            if shot["acceptance_status"] or shot["acceptance_notes"]:
                story.append(
                    Paragraph(
                        f'Acceptance: {shot["acceptance_status"] or "-"} | Notes: {shot["acceptance_notes"][:180] or "-"}',
                        small_style,
                    )
                )
            story.append(Spacer(1, 3 * mm))
    else:
        story.append(Paragraph("No deliverable shots are available in the current export scope.", small_style))

    doc.build(story)
    return buffer.getvalue()


@app.get("/api/books/{book_id}/export-records")
def get_production_export_records(
    book_id: int,
    record_type: str | None = Query(default=None),
    episode: int | None = Query(default=None),
    status: str | None = Query(default=None),
    export_format: str | None = Query(default=None, alias="format"),
    query: str | None = Query(default=None),
    limit: int | None = Query(default=None, ge=1, le=500),
    offset: int = Query(default=0, ge=0),
):
    from models import ProductionExportRecord, Session

    with Session() as s:
        rows = s.query(ProductionExportRecord).filter(
            ProductionExportRecord.book_id == book_id,
        ).order_by(ProductionExportRecord.created_at.desc(), ProductionExportRecord.id.desc()).all()
        records = [
            record
            for record in (_serialize_production_export_record(row) for row in rows)
            if _production_export_record_matches_filters(
                record,
                record_type=record_type,
                episode=episode,
                status=status,
                export_format=export_format,
                query_text=query,
            )
        ]
        total = len(records)
        paged_records = records[offset : offset + limit] if limit is not None else records[offset:]
        return {
            "book_id": book_id,
            "records": paged_records,
            "total": total,
            "limit": limit,
            "offset": offset,
            "returned": len(paged_records),
            "has_more": offset + len(paged_records) < total,
            "filters": {
                "record_type": record_type,
                "episode": episode,
                "status": status,
                "format": export_format,
                "query": query,
            },
        }


@app.post("/api/books/{book_id}/export-records")
def create_production_export_record(book_id: int, req: ProductionExportRecordRequest):
    from models import Book, ProductionExportRecord, Session

    now = datetime.utcnow()
    with Session() as s:
        book = s.query(Book).filter(Book.id == book_id).first()
        if not book:
            raise HTTPException(status_code=404, detail="Book not found")

        meta_info = dict(req.meta_info or {})
        episode_value = meta_info.get("episode")
        try:
            episode = int(episode_value) if episode_value is not None else None
        except (TypeError, ValueError):
            episode = None
        qa_gate = _build_qa_delivery_gate(s, book_id, episode)
        status = req.status
        blocked_shots = req.blocked_shots
        summary = req.summary
        if qa_gate["blocked"]:
            blocked_codes = _coerce_string_list(meta_info.get("blocked_codes"))
            if "qa_blocked" not in blocked_codes:
                blocked_codes.append("qa_blocked")
            blocked_reasons = _coerce_string_list(meta_info.get("blocked_reasons"))
            qa_blocked_reason = _build_qa_delivery_blocked_reason(qa_gate)
            if not any(str(item).startswith("QA 待处理") for item in blocked_reasons):
                blocked_reasons.append(qa_blocked_reason)
            meta_info["blocked_codes"] = blocked_codes
            meta_info["blocked_reasons"] = blocked_reasons
            meta_info["qa_delivery_gate"] = qa_gate
            status = "blocked"
            blocked_shots = max(int(blocked_shots or 0), 1)
            if not str(summary or "").strip() or req.status == "completed":
                summary = qa_blocked_reason
        elif qa_gate["total_issue_count"] > 0:
            meta_info["qa_delivery_gate"] = qa_gate

        row = ProductionExportRecord(
            book_id=book_id,
            export_format=req.export_format,
            status=status,
            total_shots=req.total_shots,
            deliverable_shots=req.deliverable_shots,
            pending_review_shots=req.pending_review_shots,
            blocked_shots=blocked_shots,
            summary=summary,
            meta_info=json.dumps(meta_info, ensure_ascii=False),
            created_at=now,
            updated_at=now,
        )
        s.add(row)
        s.commit()
        s.refresh(row)
        return _serialize_production_export_record(row)


@app.get("/api/books/{book_id}/export-pdf")
def export_production_pdf(book_id: int, episode: int | None = Query(default=None)):
    from io import BytesIO
    from fastapi.responses import StreamingResponse
    from models import Book, Script, Session, StoryboardShot

    with Session() as s:
        book = s.query(Book).filter(Book.id == book_id).first()
        if not book:
            raise HTTPException(status_code=404, detail="Book not found")
        scripts_query = s.query(Script).filter(Script.book_id == book_id)
        shots_query = s.query(StoryboardShot).filter(StoryboardShot.book_id == book_id)
        if episode is not None:
            scripts_query = scripts_query.filter(Script.episode == episode)
            shots_query = shots_query.filter(StoryboardShot.episode == episode)
        qa_gate = _build_qa_delivery_gate(s, book_id, episode)
        if qa_gate["blocked"]:
            raise HTTPException(
                status_code=409,
                detail={
                    "code": "qa_blocked",
                    "message": "当前导出范围仍有可执行 QA 问题，不能生成正式 PDF 交付件。",
                    "qa_delivery_gate": qa_gate,
                },
            )
        scripts = scripts_query.order_by(Script.episode.asc()).all()
        all_storyboard_rows = shots_query.order_by(StoryboardShot.episode.asc(), StoryboardShot.shot_id.asc()).all()

    storyboard_rows = [shot for shot in all_storyboard_rows if _is_storyboard_shot_deliverable_for_export(shot)]
    pdf_bytes = _build_production_export_pdf(
        book,
        scripts,
        storyboard_rows,
        {
            "total_shots": len(all_storyboard_rows),
            "deliverable_shots": len(storyboard_rows),
            "blocked_shots": max(len(all_storyboard_rows) - len(storyboard_rows), 0),
        },
    )
    safe_title = "".join(ch if ch.isascii() and (ch.isalnum() or ch in "-_") else "_" for ch in (book.title or "project"))
    filename = f"{safe_title}-episode-{episode}-production-export.pdf" if episode is not None else f"{safe_title}-production-export.pdf"
    headers = {"Content-Disposition": f'attachment; filename="{filename}"'}
    return StreamingResponse(BytesIO(pdf_bytes), media_type="application/pdf", headers=headers)


