@app.post("/api/books/{book_id}/qa/issues/{issue_key}/auto-fix")
def auto_fix_qa_issue(book_id: int, issue_key: str, req: QAAutoFixRequest, background: BackgroundTasks):
    from models import QAIssue, Script, ScriptVersion

    version_id = None
    diff_text = ""
    selected_option = None
    issue_episode = None
    with Session() as session:
        issue = session.query(QAIssue).filter(
            QAIssue.book_id == book_id,
            QAIssue.issue_key == issue_key,
        ).first()
        if not issue:
            raise HTTPException(status_code=404, detail="QA issue not found.")

        script = session.query(Script).filter(
            Script.book_id == book_id,
            Script.episode == issue.episode,
        ).first()
        if not script:
            raise HTTPException(status_code=404, detail="Script not found.")

        current_meta = safe_json_loads(issue.meta_info, {})
        failed_rechecks = int(current_meta.get("auto_fix_recheck_fail_count") or 0)
        if failed_rechecks >= int(req.stop_after_failed_rechecks or 2):
            raise HTTPException(status_code=409, detail=f"Auto-fix stopped because this issue has already failed recheck {failed_rechecks} times.")

        issue_episode = issue.episode
        excerpt, options = _generate_qa_fix_options_for_issue(
            issue,
            script,
            req.mode or issue.fix_mode or "auto",
            option_count=req.option_count,
            custom_requirement=req.custom_requirement,
        )
        selected_option = _select_best_qa_fix_option(issue, excerpt, options)
        if not selected_option:
            raise HTTPException(status_code=400, detail="No usable auto-fix option generated.")
        guard = _qa_fix_guard_result(
            issue,
            script.content or "",
            str(selected_option.get("patched_text") or ""),
            int(req.max_diff_lines or 16),
            float(req.max_length_delta_ratio or 0.8),
        )
        if guard["blocked"]:
            raise HTTPException(status_code=409, detail=f"Auto-fix blocked by safety guard: {', '.join(guard['reasons'])}")

        meta = safe_json_loads(issue.meta_info, {})
        meta["repair_options"] = options
        meta["last_generated_mode"] = req.mode
        meta["auto_fix_selected_option_id"] = selected_option.get("id") or "A"
        meta["auto_fix_selection_reason"] = "best-scored-option"
        meta["auto_fix_guard"] = {
            "changed_line_count": guard["changed_line_count"],
            "length_delta_ratio": guard["length_delta_ratio"],
        }
        issue.meta_info = json.dumps(meta, ensure_ascii=False)
        version_id, diff_text, issue_episode = _apply_qa_fix_internal(
            session,
            book_id,
            issue,
            script,
            req.mode or issue.fix_mode or "auto",
            str(selected_option.get("patched_text") or ""),
            f"Auto fix: {issue.title or issue.description}",
            str(selected_option.get("id") or "A"),
            req.operator_name,
            req.rerun_qa,
        )
        session.commit()

    recheck_payload = None
    if req.rerun_qa:
        background.add_task(_run_episode_recheck_in_background, book_id, issue_episode, version_id, issue_key)
        recheck_payload = {"status": "running", "message": "QA recheck started in background."}

    with Session() as session:
        version = session.query(ScriptVersion).filter(ScriptVersion.id == version_id).first()
        issue = session.query(QAIssue).filter(QAIssue.book_id == book_id, QAIssue.issue_key == issue_key).first()

    return {
        "ok": True,
        "issue": _serialize_qa_issue(issue),
        "episode": issue_episode,
        "selected_option": selected_option,
        "selection_reason": "best-scored-option",
        "guard": {
            "changed_line_count": guard["changed_line_count"],
            "length_delta_ratio": guard["length_delta_ratio"],
        },
        "diff_text": diff_text,
        "version": _serialize_script_version(version),
        "recheck": recheck_payload,
    }


@app.post("/api/books/{book_id}/qa/{episode}/apply-edits")
def apply_script_qa_edits(book_id: int, episode: int, req: ScriptEditsApplyRequest, background: BackgroundTasks):
    """Apply a validated anchored edit batch and version it.

    Edits must already be anchored to ``beat_id`` values.  ``frozen_beat_fingerprints``
    may be passed from a frozen evidence packet; when present it is used to reject
    stale edits whose target beat changed since the packet was captured.  This
    endpoint never calls an LLM.
    """
    from models import QAIssue, Script, ScriptVersion

    with Session() as session:
        script = session.query(Script).filter_by(book_id=book_id, episode=episode).first()
        if not script:
            raise HTTPException(status_code=404, detail="Script not found.")
        before = str(script.content or "")
        validation = validate_edits(
            before,
            episode,
            req.edits,
            frozen_beats=req.frozen_beat_fingerprints or None,
        )
        if not validation["valid"]:
            raise HTTPException(status_code=409, detail={"conflicts": validation["conflicts"]})
        after, applied = apply_edits(before, episode, req.edits)
        if after == before:
            raise HTTPException(status_code=409, detail={"conflicts": ["应用后文本无变化。"]})
        issue = session.query(QAIssue).filter_by(book_id=book_id, issue_key=req.qa_issue_key).first() if req.qa_issue_key else None
        verification = None
        if req.resolution_criteria and issue:
            passed, detail = evaluate_resolution_criteria(after, episode, req.resolution_criteria)
            verification = {"passed": passed, "detail": detail}
        _ensure_script_baseline_version(session, script)
        diff_text = _build_script_diff(before, after, episode)
        version_no = _next_script_version_no(session, book_id, episode)
        version = ScriptVersion(
            book_id=book_id,
            episode=episode,
            script_id=script.id,
            version_no=version_no,
            label=f"v{version_no} 锚定编辑：{(req.change_reason or 'QA 修复').strip()[:16]}",
            change_type="qa_edit",
            change_reason=req.change_reason or "",
            qa_issue_key=req.qa_issue_key or "",
            operator_name=req.operator_name or "user",
            content_before=before,
            content_after=after,
            diff_text=diff_text,
            recheck_status="running" if req.rerun_qa else "not_run",
            recheck_summary="QA 复检已启动。" if req.rerun_qa else "未启动复检。",
            meta_info=json.dumps({"pre_apply_beats": [b.as_dict() for b in build_script_beats(before, episode)], "applied_edits": applied}, ensure_ascii=False),
        )
        session.add(version)
        script.content = after
        script.word_count = len(after or "")
        if issue:
            if verification is not None:
                issue.fix_status = "resolved" if verification["passed"] else "needs_refinement"
                issue.status_reason = "锚定编辑已应用；" + ("判定通过。" if verification["passed"] else "判定未达标，待定稿。")
            else:
                issue.fix_status = "in_progress"
                issue.status_reason = "锚定编辑已应用，正在复检。"
            issue.updated_at = datetime.now()
        session.commit()
        session.refresh(version)

    recheck_payload = None
    if req.rerun_qa:
        background.add_task(_run_episode_recheck_in_background, book_id, episode, version.id, req.qa_issue_key or None)
        recheck_payload = {"status": "running", "message": "QA 复检已启动。"}
    return {
        "ok": True,
        "episode": episode,
        "version": _serialize_script_version(version),
        "applied": applied,
        "diff_text": diff_text,
        "recheck": recheck_payload,
        "verification": verification,
    }


def _compute_qa_issue_route(session, book_id: int, episode: int, issue) -> dict[str, Any]:
    """Evaluate one issue's anchor reliability + criteria to decide auto vs human."""
    from models import Script
    script = session.query(Script).filter_by(book_id=book_id, episode=episode).first()
    content = str((script.content if script else "") or "")
    beat_ids, reliable = find_issue_beats(
        content,
        episode,
        source_excerpt=issue.source_excerpt or "",
        line_start=issue.line_start,
        line_end=issue.line_end,
        script_section=issue.script_section or "",
    )
    criteria = build_resolution_criteria(
        {"type": issue.issue_type, "title": issue.title, "description": issue.description},
        beat_ids if reliable else [],
    )
    route = route_issue({"type": issue.issue_type, "title": issue.title, "description": issue.description}, reliable, criteria)
    return {"route": route, "beat_ids": beat_ids if reliable else [], "beat_anchor_reliable": reliable, "criteria_kind": criteria.get("kind"), "criteria_reason": criteria.get("reason") or ""}


@app.get("/api/books/{book_id}/qa/{episode}/routing-plan")
def qa_routing_plan(book_id: int, episode: int):
    """Read-only routing plan; never mutates issues or the script."""
    from models import QAIssue
    with Session() as session:
        rows = session.query(QAIssue).filter_by(book_id=book_id, episode=episode).order_by(QAIssue.id.asc()).all()
        items = []
        for issue in rows:
            meta = safe_json_loads(issue.meta_info, {})
            if str(meta.get("workflow_status") or "") in {"resolved", "wont_fix"} or issue.fix_status == "recheck_passed":
                continue
            info = _compute_qa_issue_route(session, book_id, episode, issue)
            items.append({"issue_key": issue.issue_key, "type": issue.issue_type, "title": issue.title, **info})
        return {"episode": episode, "items": items}


@app.post("/api/books/{book_id}/qa/{episode}/route-human-queue")
def apply_qa_human_routing(book_id: int, episode: int):
    """Mark subjective / non-decidable open issues as human-review queue items.

    This only writes the issue routing metadata.  It never calls an LLM, never
    rewrites the script, and never creates a version.  Auto-routed issues are
    left untouched so they can go through the edit pipeline later.
    """
    from models import QAIssue
    with Session() as session:
        rows = session.query(QAIssue).filter_by(book_id=book_id, episode=episode).order_by(QAIssue.id.asc()).all()
        human = []
        auto = []
        for issue in rows:
            meta = safe_json_loads(issue.meta_info, {})
            if str(meta.get("workflow_status") or "") in {"resolved", "wont_fix"} or issue.fix_status == "recheck_passed":
                continue
            info = _compute_qa_issue_route(session, book_id, episode, issue)
            if info["route"] == "human":
                meta["human_review_required"] = True
                meta["routing"] = "human"
                meta["routing_reason"] = info["criteria_reason"] or "主观项 / 无可靠 beat 锚点，转人工定稿。"
                issue.meta_info = json.dumps(meta, ensure_ascii=False)
                issue.status_reason = "转人工定稿。"
                issue.updated_at = datetime.now()
                human.append(issue.issue_key)
            else:
                auto.append(issue.issue_key)
        session.commit()
        return {"episode": episode, "human": human, "auto": auto, "human_count": len(human), "auto_count": len(auto)}


_qa_auto_fix_tasks: dict[str, dict[str, Any]] = {}


def _set_qa_auto_fix_task_state(task_id: str, state: dict[str, Any]) -> None:
    _qa_auto_fix_tasks[task_id] = state
    _persist_task_state(task_id, "qa-auto-fix", state)


def _run_qa_auto_fix_episode_task(task_id: str, book_id: int, episode: int, request_payload: dict[str, Any]) -> None:
    """Finish an explicitly requested repair batch outside the browser request.

    LLM-backed repair options can take longer than a reverse proxy/browser
    request. Persisting this task keeps the exact same safety guards and script
    versioning, while allowing the UI to poll progress instead of timing out.
    """
    state = _qa_auto_fix_tasks.get(task_id) or _load_persisted_task_state(task_id, "qa-auto-fix") or {}
    try:
        requested = QAAutoFixRequest.model_validate(request_payload)
        inline_request = requested.model_copy(update={"async_mode": False, "rerun_qa": False})
        state.update({
            "task_id": task_id,
            "task_kind": "qa-auto-fix",
            "book_id": book_id,
            "episode": episode,
            "status": "running",
            "progress": 10,
            "current_step": "正在生成受控修复方案",
            "started_at": datetime.utcnow().isoformat(),
            "error": None,
        })
        _set_qa_auto_fix_task_state(task_id, state)

        # Reuse the synchronous implementation so option selection, diff guards,
        # version snapshots and per-issue failure reporting remain identical.
        result = auto_fix_qa_episode(book_id, episode, inline_request, BackgroundTasks())
        if isinstance(result, JSONResponse):
            raise RuntimeError("Unexpected nested async QA repair response.")
        state.update({"result": result, "progress": 88, "current_step": "修复批次已完成，正在准备复检"})
        _set_qa_auto_fix_task_state(task_id, state)

        if requested.rerun_qa and (result.get("applied") or result.get("failed")):
            state.update({"status": "rechecking", "progress": 92, "current_step": "正在运行整集 QA 复检"})
            _set_qa_auto_fix_task_state(task_id, state)
            state["recheck"] = _run_episode_qa_and_sync(book_id, episode)

        result_failed = int(result.get("failed_count") or 0)
        state.update({
            "status": "done" if result_failed == 0 else "partial",
            "progress": 100,
            "current_step": "QA 批量修复完成",
            "finished_at": datetime.utcnow().isoformat(),
        })
        _set_qa_auto_fix_task_state(task_id, state)
    except Exception as exc:
        state.update({
            "task_id": task_id,
            "task_kind": "qa-auto-fix",
            "book_id": book_id,
            "episode": episode,
            "status": "error",
            "progress": 100,
            "current_step": "QA 批量修复失败",
            "error": str(exc),
            "finished_at": datetime.utcnow().isoformat(),
        })
        _set_qa_auto_fix_task_state(task_id, state)
        logger.exception("QA auto-fix task %s failed", task_id)


@app.get("/api/books/{book_id}/qa/auto-fix/tasks/{task_id}")
def get_qa_auto_fix_task(book_id: int, task_id: str):
    task = _qa_auto_fix_tasks.get(task_id) or _load_persisted_task_state(task_id, "qa-auto-fix")
    if not task or int(task.get("book_id") or 0) != int(book_id):
        raise HTTPException(status_code=404, detail="QA auto-fix task not found.")
    _qa_auto_fix_tasks.setdefault(task_id, task)
    return task


@app.post("/api/books/{book_id}/qa/episodes/{episode}/auto-fix")
def auto_fix_qa_episode(book_id: int, episode: int, req: QAAutoFixRequest, background: BackgroundTasks):
    if req.async_mode:
        task_id = f"qa-auto-fix-{uuid.uuid4().hex[:12]}"
        task_state = {
            "task_id": task_id,
            "task_kind": "qa-auto-fix",
            "book_id": book_id,
            "episode": episode,
            "status": "queued",
            "progress": 0,
            "current_step": "已排队，等待执行受控修复",
            "created_at": datetime.utcnow().isoformat(),
            "request": req.model_dump(by_alias=False, mode="json"),
        }
        _set_qa_auto_fix_task_state(task_id, task_state)
        background.add_task(
            _run_qa_auto_fix_episode_task,
            task_id,
            book_id,
            episode,
            req.model_dump(by_alias=False, mode="json"),
        )
        return JSONResponse(status_code=202, content={"ok": True, "task_id": task_id, "status": "queued", "async_mode": True})
    from models import QAIssue, Script, ScriptVersion

    applied = []
    failed = []
    version_ids = []
    with Session() as session:
        script = session.query(Script).filter(
            Script.book_id == book_id,
            Script.episode == episode,
        ).first()
        if not script:
            raise HTTPException(status_code=404, detail="Script not found.")

        issues = session.query(QAIssue).filter(
            QAIssue.book_id == book_id,
            QAIssue.episode == episode,
        ).all()
        open_issues = [item for item in issues if item.fix_status not in {"recheck_passed", "rechecking"}]
        ordered_issues = sorted(
            open_issues,
            key=lambda item: (
                0 if item.line_start else 1,
                -(item.line_start or 0),
                -int(item.id or 0),
            ),
        )[: max(1, int(req.max_issues or 10))]

        for issue in ordered_issues:
            try:
                issue_meta = safe_json_loads(issue.meta_info, {})
                failed_rechecks = int(issue_meta.get("auto_fix_recheck_fail_count") or 0)
                if failed_rechecks >= int(req.stop_after_failed_rechecks or 2):
                    failed.append({
                        "issue_id": issue.issue_key,
                        "title": issue.title,
                        "failure_kind": "stopped_after_failed_rechecks",
                        "reason": f"Auto-fix stopped because recheck has already failed {failed_rechecks} times.",
                    })
                    continue
                excerpt, options = _generate_qa_fix_options_for_issue(
                    issue,
                    script,
                    req.mode or issue.fix_mode or "auto",
                    option_count=req.option_count,
                    custom_requirement=req.custom_requirement,
                )
                selected_option = _select_best_qa_fix_option(issue, excerpt, options)
                if not selected_option:
                    failed.append({
                        "issue_id": issue.issue_key,
                        "title": issue.title,
                        "failure_kind": "no_usable_option",
                        "reason": "No usable auto-fix option generated.",
                    })
                    continue
                guard = _qa_fix_guard_result(
                    issue,
                    script.content or "",
                    str(selected_option.get("patched_text") or ""),
                    int(req.max_diff_lines or 16),
                    float(req.max_length_delta_ratio or 0.8),
                )
                if guard["blocked"]:
                    failed.append({
                        "issue_id": issue.issue_key,
                        "title": issue.title,
                        "failure_kind": "safety_guard_blocked",
                        "reason": f"Auto-fix blocked by safety guard: {', '.join(guard['reasons'])}",
                    })
                    continue
                if guard["changed_line_count"] <= 0:
                    # A fix that leaves the script byte-identical is not a repair;
                    # accept only options that materially alter the episode text.
                    fail_count = int(issue_meta.get("auto_fix_recheck_fail_count") or 0) + 1
                    adjusted_meta = dict(issue_meta)
                    adjusted_meta["auto_fix_recheck_fail_count"] = fail_count
                    issue.meta_info = json.dumps(adjusted_meta, ensure_ascii=False)
                    failed.append({
                        "issue_id": issue.issue_key,
                        "title": issue.title,
                        "failure_kind": "no_usable_option",
                        "reason": "Selected fix produces no change to the script; refusing no-op repair.",
                    })
                    continue

                meta = safe_json_loads(issue.meta_info, {})
                meta["repair_options"] = options
                meta["last_generated_mode"] = req.mode
                meta["auto_fix_selected_option_id"] = selected_option.get("id") or "A"
                meta["auto_fix_selection_reason"] = "best-scored-option"
                meta["auto_fix_guard"] = {
                    "changed_line_count": guard["changed_line_count"],
                    "length_delta_ratio": guard["length_delta_ratio"],
                }
                issue.meta_info = json.dumps(meta, ensure_ascii=False)
                version_id, diff_text, _ = _apply_qa_fix_internal(
                    session,
                    book_id,
                    issue,
                    script,
                    req.mode or issue.fix_mode or "auto",
                    str(selected_option.get("patched_text") or ""),
                    f"Episode auto-fix: {issue.title or issue.description}",
                    str(selected_option.get("id") or "A"),
                    req.operator_name,
                    False,
                )
                version_ids.append(version_id)
                applied.append({
                    "issue_id": issue.issue_key,
                    "title": issue.title,
                    "issue_type": issue.issue_type,
                    "option_id": selected_option.get("id") or "A",
                    "selection_reason": "best-scored-option",
                    "strategy": selected_option.get("strategy") or "",
                    "guard": {
                        "changed_line_count": guard["changed_line_count"],
                        "length_delta_ratio": guard["length_delta_ratio"],
                    },
                    "diff_text": diff_text,
                    "version_id": version_id,
                })
            except Exception as exc:
                failed.append({
                    "issue_id": issue.issue_key,
                    "title": issue.title,
                    "failure_kind": "runtime_error",
                    "reason": str(exc),
                })

        session.commit()

    recheck_payload = None
    if req.rerun_qa and (applied or failed):
        background.add_task(_run_episode_recheck_in_background, book_id, episode, None, None)
        recheck_payload = {"status": "running", "message": "Episode QA recheck started in background."}

    with Session() as session:
        versions = session.query(ScriptVersion).filter(
            ScriptVersion.id.in_(version_ids)
        ).order_by(ScriptVersion.version_no.desc(), ScriptVersion.id.desc()).all() if version_ids else []

    return {
        "ok": True,
        "episode": episode,
        "applied_count": len(applied),
        "failed_count": len(failed),
        "applied": applied,
        "failed": failed,
        "report": {
            "episode": episode,
            "applied_count": len(applied),
            "failed_count": len(failed),
            "failed_summary": _summarize_qa_auto_fix_failed_items(failed),
            "applied": applied,
            "failed": failed,
        },
        "versions": [_serialize_script_version(version) for version in versions],
        "recheck": recheck_payload,
    }


@app.post("/api/books/{book_id}/qa/issues/{issue_key}/apply-fix")
def apply_qa_fix(book_id: int, issue_key: str, req: QAApplyFixRequest, background: BackgroundTasks):
    from models import QAIssue, Script, ScriptVersion

    issue_episode = None
    version_id = None
    with Session() as session:
        issue = session.query(QAIssue).filter(
            QAIssue.book_id == book_id,
            QAIssue.issue_key == issue_key,
        ).first()
        if not issue:
            raise HTTPException(status_code=404, detail="QA issue not found.")

        script = session.query(Script).filter(
            Script.book_id == book_id,
            Script.episode == issue.episode,
        ).first()
        if not script:
            raise HTTPException(status_code=404, detail="Script not found.")
        if not (req.patched_text or "").strip():
            raise HTTPException(status_code=400, detail="patched_text is required.")

        version_id, diff_text, issue_episode = _apply_qa_fix_internal(
            session,
            book_id,
            issue,
            script,
            req.mode,
            req.patched_text.strip(),
            req.change_reason or issue.description,
            req.option_id,
            req.operator_name or "user",
            req.rerun_qa,
        )
        session.commit()

    recheck_payload = None
    if req.rerun_qa:
        background.add_task(_run_episode_recheck_in_background, book_id, issue_episode, version_id, issue_key)
        recheck_payload = {"status": "running", "message": "QA recheck started in background."}
    with Session() as session:
        version = session.query(ScriptVersion).filter(ScriptVersion.id == version_id).first()

    return {
        "ok": True,
        "issue_id": issue_key,
        "episode": issue_episode,
        "diff_text": diff_text,
        "version": _serialize_script_version(version),
        "recheck": recheck_payload,
    }


@app.post("/api/books/{book_id}/scripts/{episode}/versions/{version_id}/rollback")
def rollback_script_version(book_id: int, episode: int, version_id: int, req: QARollbackRequest, background: BackgroundTasks):
    from models import QAIssue, Script, ScriptVersion

    created_version_id = None
    with Session() as session:
        script = session.query(Script).filter(
            Script.book_id == book_id,
            Script.episode == episode,
        ).first()
        if not script:
            raise HTTPException(status_code=404, detail="Script not found.")

        target = session.query(ScriptVersion).filter(
            ScriptVersion.book_id == book_id,
            ScriptVersion.episode == episode,
            ScriptVersion.id == version_id,
        ).first()
        if not target:
            raise HTTPException(status_code=404, detail="Version not found.")

        _ensure_script_baseline_version(session, script)
        before_text = script.content or ""
        rollback_text = target.content_before if target.change_type != "baseline" else target.content_after
        diff_text = _build_script_diff(before_text, rollback_text, episode)
        version_no = _next_script_version_no(session, book_id, episode)
        version = ScriptVersion(
            book_id=book_id,
            episode=episode,
            script_id=script.id,
            version_no=version_no,
            label=f"v{version_no} 回滚到 {target.label}",
            change_type="rollback",
            change_reason=f"Rollback from version {target.id}",
            qa_issue_key=target.qa_issue_key or "",
            operator_name=req.operator_name or "user",
            content_before=before_text,
            content_after=rollback_text,
            diff_text=diff_text,
            recheck_status="running" if req.rerun_qa else "not_run",
            recheck_summary="QA recheck is running in background." if req.rerun_qa else "Rolled back without recheck",
            meta_info=json.dumps({"rollback_target_id": target.id}, ensure_ascii=False),
        )
        session.add(version)
        script.content = rollback_text
        script.word_count = len(rollback_text or "")
        if target.qa_issue_key:
            issue = session.query(QAIssue).filter(QAIssue.issue_key == target.qa_issue_key).first()
            if issue:
                issue.fix_status = "rolled_back"
                issue.status_reason = f"Rolled back from {target.label}"
                issue.updated_at = datetime.now()
        session.commit()
        session.refresh(version)
        created_version_id = version.id

    recheck_payload = None
    if req.rerun_qa:
        background.add_task(_run_episode_recheck_in_background, book_id, episode, created_version_id, None)
        recheck_payload = {"status": "running", "message": "QA recheck started in background."}
    with Session() as session:
        version = session.query(ScriptVersion).filter(ScriptVersion.id == created_version_id).first()

    return {
        "ok": True,
        "episode": episode,
        "diff_text": diff_text,
        "version": _serialize_script_version(version),
        "recheck": recheck_payload,
    }


@app.patch("/api/books/{book_id}")
def update_book(book_id: int, data: dict):
    """Update book metadata, e.g. rename."""
    from models import Session, Book
    with Session() as s:
        book = s.get(Book, book_id)
        if not book:
            raise HTTPException(status_code=404, detail="Book not found")
        if "title" in data:
            book.title = data["title"]
        s.commit()
        return {"ok": True, "title": book.title}


@app.put("/api/bibles/{book_id}")
def update_bible(book_id: int, data: dict):
    """Save edited bible content."""
    from models import Session, BookBible
    with Session() as s:
        bible = s.query(BookBible).filter(BookBible.book_id == book_id).first()
        if not bible:
            bible = BookBible(book_id=book_id, content=data.get("content", ""))
            s.add(bible)
        else:
            bible.content = data.get("content", "")
        s.commit()
    return {"ok": True}


@app.put("/api/outlines/{outline_id}")
def update_outline(outline_id: int, data: dict):
    """Save edited outline."""
    from models import Session, EpisodeOutline
    with Session() as s:
        outline = s.query(EpisodeOutline).filter(EpisodeOutline.id == outline_id).first()
        if not outline:
            raise HTTPException(status_code=404, detail="Outline not found")
        if "title" in data:
            outline.title = data["title"]
        if "core_event" in data:
            outline.core_event = data["core_event"]
        if "opening_hook" in data:
            outline.opening_hook = data["opening_hook"]
        if "core_conflict" in data:
            outline.core_conflict = data["core_conflict"]
        if "climax" in data:
            outline.climax = data["climax"]
        if "ending_hook" in data:
            outline.ending_hook = data["ending_hook"]
        s.commit()
    return {"ok": True}


@app.put("/api/scripts/{script_id}")
def update_script(script_id: int, data: dict):
    """Save edited script."""
    from models import Session, Script
    with Session() as s:
        script = s.query(Script).filter(Script.id == script_id).first()
        if not script:
            raise HTTPException(status_code=404, detail="Script not found")
        if "content" in data:
            script.content = data["content"]
            script.word_count = len(data["content"])
        s.commit()
    return {"ok": True}


@app.post("/api/cli/serve")
def serve_check():
    return {"ok": True, "message": "DevCanvas server running"}


if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8765)
